float_sub() {
  python3 - "$1" "$2" <<'PY'
import sys
print(float(sys.argv[1]) - float(sys.argv[2]))
PY
}
FUEL_EFFECTIVE_INIT_X="${FUEL_INIT_X}"
FUEL_EFFECTIVE_INIT_Y="${FUEL_INIT_Y}"
