  FUEL_EFFECTIVE_INIT_X="$(float_sub "${FUEL_INIT_X}" "${FUEL_FRAME_OFFSET_X}")"
  FUEL_EFFECTIVE_INIT_Y="$(float_sub "${FUEL_INIT_Y}" "${FUEL_FRAME_OFFSET_Y}")"
  FUEL_EFFECTIVE_INIT_Z="$(float_sub "${FUEL_INIT_Z}" "${FUEL_FRAME_OFFSET_Z}")"
  FUEL_EFFECTIVE_BOX_MIN_X="$(float_sub "${FUEL_BOX_MIN_X}" "${FUEL_FRAME_OFFSET_X}")"
  FUEL_EFFECTIVE_BOX_MIN_Y="$(float_sub "${FUEL_BOX_MIN_Y}" "${FUEL_FRAME_OFFSET_Y}")"
  FUEL_EFFECTIVE_BOX_MIN_Z="$(float_sub "${FUEL_BOX_MIN_Z}" "${FUEL_FRAME_OFFSET_Z}")"
  FUEL_EFFECTIVE_BOX_MAX_X="$(float_sub "${FUEL_BOX_MAX_X}" "${FUEL_FRAME_OFFSET_X}")"
  FUEL_EFFECTIVE_BOX_MAX_Y="$(float_sub "${FUEL_BOX_MAX_Y}" "${FUEL_FRAME_OFFSET_Y}")"
  FUEL_EFFECTIVE_BOX_MAX_Z="$(float_sub "${FUEL_BOX_MAX_Z}" "${FUEL_FRAME_OFFSET_Z}")"
