  FUEL_EFFECTIVE_POSE_TOPIC="${FUEL_LOCAL_POSE_TOPIC}"
  FUEL_EFFECTIVE_CLOUD_TOPIC="${FUEL_LOCAL_CLOUD_TOPIC}"
  PLANNER_EFFECTIVE_ODOM_TOPIC="${FUEL_LOCAL_ODOM_TOPIC}"
  FUEL_OUTPUT_OFFSET_X="${FUEL_COMMAND_OUTPUT_OFFSET_X}"
  FUEL_OUTPUT_OFFSET_Y="${FUEL_COMMAND_OUTPUT_OFFSET_Y}"
  FUEL_OUTPUT_OFFSET_Z="${FUEL_COMMAND_OUTPUT_OFFSET_Z}"
