  FUEL_EFFECTIVE_ODOM_TOPIC="${FUEL_FASTLIO_ALIGNED_LOCAL_ODOM_TOPIC}"
  FUEL_EFFECTIVE_POSE_TOPIC="${FUEL_CLOUD_SOURCE_POSE_TOPIC}"
