    echo "PX4CTRL_ENABLE_FASTLIO_EKF_FUSION=true requires PX4CTRL_ODOM_SOURCE=mavros_local; FAST-LIO must feed PX4 EKF, not px4ctrl directly." >&2
    exit 2
  fi
  if [[ "${PX4CTRL_FASTLIO_VELOCITY_FUSION_ENABLED}" == "true" ]]; then
    PX4CTRL_FASTLIO_ODOMETRY_FUSION_ENABLED=true
  fi
  if [[ "${PX4CTRL_FASTLIO_ODOMETRY_FUSION_ENABLED}" != "true" ]]; then
    echo "FAST-LIO EKF fusion requires the unified MAVROS ODOMETRY route" >&2
    exit 2
  fi
  PX4CTRL_START_EXTERNAL_FUSION=false
  if [[ -z "${FASTLIO_ALIGNMENT_Z_SOURCE_WAS_SET}" ]]; then
    FASTLIO_ALIGNMENT_Z_SOURCE="truth"
  fi
fi
if [[ "${PX4CTRL_FASTLIO_ODOMETRY_FUSION_ENABLED}" == "true" ]]; then
  if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" != "true" ]]; then
    echo "FAST-LIO ODOMETRY fusion requires PX4CTRL_ENABLE_FASTLIO_EKF_FUSION=true" >&2
    exit 2
  fi
  if [[ -z "${PX4CTRL_EKF2_EV_CTRL_OVERRIDE}" ]] || (( (PX4CTRL_EKF2_EV_CTRL_OVERRIDE & 4) == 0 )); then
    echo "FAST-LIO ODOMETRY fusion requires PX4CTRL_EKF2_EV_CTRL_OVERRIDE with velocity bit 2 set, for example 7" >&2
    exit 2
  fi
fi
FUEL_FASTLIO_ALIGNMENT_Z_SOURCE="${FUEL_FASTLIO_ALIGNMENT_Z_SOURCE:-${FASTLIO_ALIGNMENT_Z_SOURCE}}"
PX4CTRL_ODOM_TOPIC="/uav1/mavros/local_position/odom"
PX4CTRL_PATH_FRAME="${PX4CTRL_PATH_FRAME:-world}"
PLANNER_RAW_POSITION_CMD_TOPIC=""
PLANNER_ENABLE_CMD_SAFETY_ADAPTER="false"
REQUESTED_PLANNER_MISSION_MODE="${PLANNER_MISSION_MODE:-}"
PLANNER_MISSION_MODE="fixed_goal"
PLANNER_BSPLINE_MSG_PACKAGE="traj_utils"
PLANNER_CMD_SMOOTH_ENABLE="false"
PLANNER_CMD_SMOOTH_MAX_SPEED_MPS="0"
PLANNER_CMD_SMOOTH_MAX_STEP_M="0"
PLANNER_CMD_SMOOTH_ZERO_DYNAMICS="true"
PLANNER_CMD_MOTION_TIME_BASIS="wall"
PLANNER_CMD_RECOMPUTE_VELOCITY_FROM_POSITION="false"
PLANNER_CMD_MAX_VELOCITY_MPS="${PLANNER_CMD_MAX_VELOCITY_MPS:-0}"
PLANNER_CMD_MAX_ACCELERATION_MPS2="${PLANNER_CMD_MAX_ACCELERATION_MPS2:-0}"
PLANNER_CMD_MAX_LATERAL_ACCELERATION_MPS2="${PLANNER_CMD_MAX_LATERAL_ACCELERATION_MPS2:-0}"
