    DIFF_CMD_SAFETY_MAX_POSITION_JUMP_M="${HIGHSTAR_RAW_CMD_MAX_POSITION_JUMP_M}"
    DIFF_CMD_SAFETY_MAX_POSITION_JUMP_SPEED_MPS="${HIGHSTAR_RAW_CMD_MAX_POSITION_JUMP_SPEED_MPS}"
    PLANNER_CMD_ODOM_TARGET_GUARD_ENABLE="${HIGHSTAR_ODOM_TARGET_GUARD_ENABLE}"
    PLANNER_CMD_MAX_TARGET_DISTANCE_FROM_ODOM_M="${HIGHSTAR_MAX_TARGET_DISTANCE_FROM_ODOM_M}"
    PLANNER_CMD_MAX_XY_TARGET_DISTANCE_FROM_ODOM_M="${HIGHSTAR_MAX_XY_TARGET_DISTANCE_FROM_ODOM_M}"
    if [[ -z "${OCCUPANCY_TOPIC_WAS_SET}" ]]; then
      OCCUPANCY_TOPIC="/murder_demo/block_map/voxvis"
      OCCUPANCY_MSG_TYPE="markerarray"
    fi
    if [[ -z "${OCCUPANCY_REVIEW_SOURCE_TOPIC_WAS_SET}" ]]; then
      OCCUPANCY_REVIEW_SOURCE_TOPIC=""
    fi
    ;;
  *)
    echo "Unsupported PLANNER_VARIANT=${PLANNER_VARIANT}; expected ego_v1, egov2, diff_planner, fuel, racer, falcon, uav_frontier, or highstar" >&2
    exit 2
    ;;
esac
if [[ -n "${REQUESTED_PLANNER_MISSION_MODE}" ]]; then
  case "${REQUESTED_PLANNER_MISSION_MODE}" in
    fixed_goal|exploration_stream)
      PLANNER_MISSION_MODE="${REQUESTED_PLANNER_MISSION_MODE}"
      ;;
    *)
      echo "Unsupported PLANNER_MISSION_MODE=${REQUESTED_PLANNER_MISSION_MODE}" >&2
      exit 2
      ;;
  esac
fi

if [[ "${PLANNER_VARIANT}" == "diff_planner" && "${DIFF_GOAL4_COMMON_WORLD_FRAME}" == "true" ]]; then
  # Factory L2 cloud and QGC goals are expressed in Gazebo world coordinates.
  # Keep px4ctrl on its PX4-local frame and bridge only the planner boundary.
  PLANNER_EFFECTIVE_ODOM_TOPIC="${DIFF_GOAL4_PLANNER_ODOM_TOPIC}"
  PLANNER_POSITION_CMD_TOPIC="${DIFF_GOAL4_PLANNER_POSITION_CMD_WORLD_TOPIC}"
  DIFF_GOAL4_PATH_ODOM_TOPIC="${DIFF_GOAL4_PLANNER_ODOM_TOPIC}"
fi

mkdir -p "${RESULT_DIR}"
# Keep each bounded gate's ROS logs with its evidence.  A shared ~/.ros/log
# grows across long Gazebo runs and can destabilize later spawn/transport calls.
export ROS_LOG_DIR="${RESULT_DIR}/ros_log"
mkdir -p "${ROS_LOG_DIR}"

capture_px4_ulog() {
  if [[ "${PX4_ULOG_CAPTURE_ENABLED}" != "true" || -z "${PX4_ULOG_CAPTURE_AFTER_EPOCH}" ]]; then
    return
  fi
  local latest=""
  if [[ -d "${PX4_ULOG_SEARCH_ROOT}" ]]; then
    latest="$(find "${PX4_ULOG_SEARCH_ROOT}" -type f -name '*.ulg' -newermt "@${PX4_ULOG_CAPTURE_AFTER_EPOCH}" -printf '%T@ %p\n' 2>/dev/null | sort -nr | head -1 | cut -d' ' -f2-)"
  fi
  {
    echo "search_root=${PX4_ULOG_SEARCH_ROOT}"
    echo "capture_after_epoch=${PX4_ULOG_CAPTURE_AFTER_EPOCH}"
    echo "source=${latest:-none}"
  } > "${RESULT_DIR}/px4_ulog_capture.txt"
  if [[ -n "${latest}" && -s "${latest}" ]]; then
    cp -f "${latest}" "${RESULT_DIR}/PX4_ESTIMATOR.ulg"
    stat "${RESULT_DIR}/PX4_ESTIMATOR.ulg" >> "${RESULT_DIR}/px4_ulog_capture.txt" 2>&1 || true
  fi
}

PIDS=()
cleanup() {
  set +e
  local force_cleanup="${1:-false}"
  if [[ "${KEEP_ALIVE:-false}" == "true" && "${force_cleanup}" != "force" ]]; then
    return
  fi
  for pid in "${PIDS[@]:-}"; do
    kill "${pid}" >/dev/null 2>&1 || true
  done
  sleep 2
  capture_px4_ulog
  for pid in "${PIDS[@]:-}"; do
    kill -9 "${pid}" >/dev/null 2>&1 || true
  done
  pkill -f "mosim_px4ctrl_ego_single_mission" >/dev/null 2>&1 || true
  pkill -f "mosim_goal4_pointcloud_to_world" >/dev/null 2>&1 || true
  pkill -f "goal4_pointcloud_to_world_node.py" >/dev/null 2>&1 || true
  pkill -f "mosim_goal4_clicked_goal_adapter" >/dev/null 2>&1 || true
  pkill -f "goal4_clicked_goal_adapter.py" >/dev/null 2>&1 || true
  pkill -f "mosim_accumulate_pointcloud_review" >/dev/null 2>&1 || true
  pkill -f "accumulate_pointcloud_review.py" >/dev/null 2>&1 || true
  pkill -f "mosim_goal4_position_cmd_safety_adapter" >/dev/null 2>&1 || true
  pkill -f "goal4_position_cmd_safety_adapter.py" >/dev/null 2>&1 || true
