  pkill -f "px4_ros1_runtime_overlay_.*px4" >/dev/null 2>&1 || true
  if [[ "${PRESERVE_EXISTING_ROSCORE:-false}" != "true" ]]; then
    pkill -f "rosmaster" >/dev/null 2>&1 || true
