trap cleanup EXIT

prepare_px4_ros1_runtime_overlay() {
  PX4_ROS1_OVERLAY_PKG=""
  if [[ "${PX4_ROS1_GUARD_UXRCE_DDS}" != "true" ]]; then
    return 0
  fi

  local original_px4_etc="${PX4_BUILD_DIR}/etc"
  local original_px4_bin="${PX4_BUILD_DIR}/bin"
  local original_package="${SUNRAY_PX4_DIR}/package.xml"
  local overlay_root="${RESULT_DIR}/px4_ros1_runtime_overlay_$$"
  local overlay_pkg="${overlay_root}/px4"
  local overlay_build="${overlay_pkg}/build/px4_sitl_default"
  local overlay_etc="${overlay_build}/etc"
  local overlay_rcs="${overlay_etc}/init.d-posix/rcS"
  local overlay_params="${overlay_etc}/init.d-posix/px4-rc.params"

  if [[ ! -d "${original_px4_etc}" || ! -d "${original_px4_bin}" || ! -f "${original_package}" ]]; then
    echo "PX4 ROS1 runtime overlay inputs missing under ${SUNRAY_PX4_DIR}" >&2
    exit 2
  fi

  mkdir -p "${overlay_build}"
  cp "${original_package}" "${overlay_pkg}/package.xml"
  cp -a "${original_px4_etc}" "${overlay_etc}"
  ln -s "${original_px4_bin}" "${overlay_build}/bin"

  python3 - "${overlay_rcs}" <<'PY'
import sys
from pathlib import Path

path = Path(sys.argv[1])
text = path.read_text(encoding="utf-8")
old = "uxrce_dds_client start -t udp -h 127.0.0.1 -p $uxrce_dds_port $uxrce_dds_ns"
new = """if ! uxrce_dds_client start -t udp -h 127.0.0.1 -p $uxrce_dds_port $uxrce_dds_ns
then
\techo "WARN [init] uxrce_dds_client start failed, continuing for MoSim ROS1/MAVROS gate"
fi"""
if old not in text:
    raise SystemExit(f"uxrce_dds_client start line not found in {path}")
text = text.replace(old, new, 1)
if "# MoSim ROS1 guard: force rcS success" not in text:
    text = text.rstrip() + "\n\n# MoSim ROS1 guard: force rcS success\ntrue\n"
path.write_text(text, encoding="utf-8")
PY

  # px4-rc.params is sourced after the airframe configuration and before
  # ekf2 starts. EKF2_HGT_REF is reboot-required, so a MAVROS param/set after
  # startup cannot select vision as the active height reference for this run.
  if [[ -n "${PX4CTRL_EKF2_EV_CTRL_OVERRIDE}" ]]; then
    printf '\n# MoSim external-vision startup contract\nparam set EKF2_EV_CTRL %s\n' \
      "${PX4CTRL_EKF2_EV_CTRL_OVERRIDE}" >> "${overlay_params}"
  fi
  if [[ -n "${PX4CTRL_EKF2_HGT_REF_OVERRIDE}" ]]; then
    printf 'param set EKF2_HGT_REF %s\n' \
      "${PX4CTRL_EKF2_HGT_REF_OVERRIDE}" >> "${overlay_params}"
  fi

  PX4_ROS1_OVERLAY_PKG="${overlay_pkg}"
  export PX4_ROS1_OVERLAY_PKG
  {
    echo "PX4_ROS1_GUARD_UXRCE_DDS=true"
    echo "overlay_pkg=${overlay_pkg}"
    echo "original_px4_etc=${original_px4_etc}"
    echo "patched_rcS=${overlay_rcs}"
    echo "patched_params=${overlay_params}"
    grep -n "uxrce_dds_client start" "${overlay_rcs}" || true
    grep -n "continuing for MoSim ROS1/MAVROS gate" "${overlay_rcs}" || true
    grep -n "MoSim external-vision startup contract\|EKF2_EV_CTRL\|EKF2_HGT_REF" "${overlay_params}" || true
    tail -5 "${overlay_rcs}" || true
  } > "${RESULT_DIR}/px4_ros1_runtime_overlay.txt"
}

sync_mavros_plugin_config() {
  local source_config="${MAVROS_PLUGIN_CONFIG_SOURCE:-${PROJECT_ROOT}/src/simulation/gazebo/sunray/config/px4_pluginlists.yaml}"
  local runtime_config="${SUNRAY_WS}/simulation/sunray_simulator/config/px4_pluginlists.yaml"
  if [[ ! -f "${source_config}" || ! -d "$(dirname "${runtime_config}")" ]]; then
    echo "MAVROS plugin config sync inputs missing: ${source_config} -> ${runtime_config}" >&2
    exit 2
  fi
  install -m 0644 "${source_config}" "${runtime_config}"
  {
    echo "source=${source_config}"
    echo "runtime=${runtime_config}"
    sha256sum "${source_config}" "${runtime_config}"
    echo "runtime_odom_entries"
    grep -n "odom" "${runtime_config}" || true
  } > "${RESULT_DIR}/mavros_plugin_config_sync.txt"
  if ! cmp -s "${source_config}" "${runtime_config}"; then
    echo "MAVROS plugin config did not synchronize byte-for-byte" >&2
    exit 2
  fi
}

source_env() {
  export PATH=/opt/ros/noetic/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/usr/lib/wsl/lib
  export DISABLE_ROS1_EOL_WARNINGS=1
  set +u
  source /usr/share/gazebo/setup.sh
  source /opt/ros/noetic/setup.bash
  source "${SUNRAY_PX4_DIR}/Tools/simulation/gazebo-classic/setup_gazebo.bash" \
    "${SUNRAY_PX4_DIR}" \
    "${PX4_BUILD_DIR}"
  source "${SUNRAY_WS}/devel/setup.bash"
  if [[ -f "${PX4CTRL_WS}/devel/setup.bash" ]]; then
    source "${PX4CTRL_WS}/devel/setup.bash"
  fi
  if [[ -f "${LIVOX_PLUGIN_WS}/devel/setup.bash" ]]; then
    source "${LIVOX_PLUGIN_WS}/devel/setup.bash"
  fi
  if [[ -f "${FASTLIO_WS}/devel/setup.bash" ]]; then
    source "${FASTLIO_WS}/devel/setup.bash"
  fi
  if [[ "${PLANNER_VARIANT}" == "fuel" && -f "${PLANNER_CONTROL_COMPAT_WS}/devel/setup.bash" ]]; then
    source "${PLANNER_CONTROL_COMPAT_WS}/devel/setup.bash"
  fi
  source "${PLANNER_WS}/devel/setup.bash"
  set -u

  local sunray_models="${SUNRAY_WS}/simulation/sunray_simulator/models"
  local px4_gazebo_models="${SUNRAY_PX4_DIR}/Tools/simulation/gazebo-classic/sitl_gazebo-classic/models"
  if [[ "${SUNRAY_STRIP_PX4_MODEL_PATH}" == "true" ]]; then
    GAZEBO_MODEL_PATH="$(
      python3 - "${GAZEBO_MODEL_PATH:-}" "${px4_gazebo_models}" <<'PY'
import sys
value, remove = sys.argv[1], sys.argv[2]
print(":".join(part for part in value.split(":") if part and part != remove))
PY
    )"
  fi
  local factory_model_prefix=""
  if [[ -n "${FACTORY_MODEL_PATH}" ]]; then
    factory_model_prefix="${FACTORY_MODEL_PATH}:${PROJECT_ROOT}/Config/gazebo/models:"
  fi
  local planner_control_compat_devel=""
  local planner_control_compat_src=""
  if [[ "${PLANNER_VARIANT}" == "fuel" ]]; then
    planner_control_compat_devel="${PLANNER_CONTROL_COMPAT_WS}/devel:"
    planner_control_compat_src="${PLANNER_CONTROL_COMPAT_WS}/src:"
  fi
  export CMAKE_PREFIX_PATH="${PX4CTRL_WS}/devel:${planner_control_compat_devel}${PLANNER_WS}/devel:${FASTLIO_WS}/devel:${LIVOX_PLUGIN_WS}/devel:${SUNRAY_WS}/devel:/opt/ros/noetic:${CMAKE_PREFIX_PATH:-}"
  export ROS_PACKAGE_PATH="${PX4CTRL_WS}/src:${planner_control_compat_src}${PLANNER_WS}/src:${FASTLIO_WS}/src:${PX4_ROS1_OVERLAY_PKG:+${PX4_ROS1_OVERLAY_PKG}:}${SUNRAY_PX4_DIR}:${SUNRAY_WS}:/opt/ros/noetic/share:${ROS_PACKAGE_PATH:-}"
  export PYTHONPATH="${PX4CTRL_WS}/devel/lib/python3/dist-packages:${planner_control_compat_devel:+${PLANNER_CONTROL_COMPAT_WS}/devel/lib/python3/dist-packages:}${PLANNER_WS}/devel/lib/python3/dist-packages:${FASTLIO_WS}/devel/lib/python3/dist-packages:${SUNRAY_WS}/devel/lib/python3/dist-packages:${PYTHONPATH:-}"
  export GAZEBO_MODEL_PATH="${factory_model_prefix}${sunray_models}/scence_models:${sunray_models}/drone_models:${sunray_models}/sensor_models:${sunray_models}/fake_models:${sunray_models}/ugv_models:${sunray_models}/aws_models:${sunray_models}/aws_vins_models:${GAZEBO_MODEL_PATH:-}"
  export GAZEBO_RESOURCE_PATH="${SUNRAY_WS}/simulation/sunray_simulator:${GAZEBO_RESOURCE_PATH:-}"
  export GAZEBO_PLUGIN_PATH="${LIVOX_PLUGIN_WS}/devel/lib:${SUNRAY_WS}/devel/lib:${GAZEBO_PLUGIN_PATH:-}"
  export SUNRAY_MID360_PLUGIN_DOWNSAMPLE
  export SUNRAY_LIVOX_PLUGIN_FILENAME
  export SUNRAY_MID360_CSV_FILE_NAME
  export SUNRAY_MID360_GOAL5_CSV_STRIDE
  if [[ "${PLANNER_VARIANT}" == "fuel" ]]; then
    # FUEL and the compatible EGO traj_server both ship libraries named
    # libbspline_opt.so. Keep ROS package lookup compatible-first so
    # ego_planner/traj_server resolves to the px4ctrl-compatible workspace, but
    # make FUEL's own libraries win dynamic linking for exploration_node.
    export LD_LIBRARY_PATH="${PX4CTRL_WS}/devel/lib:${PLANNER_WS}/devel/lib:${planner_control_compat_devel:+${PLANNER_CONTROL_COMPAT_WS}/devel/lib:}${FASTLIO_WS}/devel/lib:${LIVOX_PLUGIN_WS}/devel/lib:${SUNRAY_WS}/devel/lib:/opt/ros/noetic/lib:${LD_LIBRARY_PATH:-}"
  elif [[ "${PLANNER_VARIANT}" == "falcon" ]]; then
    local falcon_deps_lib="${FALCON_LOCAL_DEPS_PREFIX}/lib"
    local falcon_deps_lib64="${FALCON_LOCAL_DEPS_PREFIX}/lib64"
    local falcon_deps_usr_lib="${FALCON_LOCAL_DEPS_PREFIX}/usr/lib/x86_64-linux-gnu"
    export LD_LIBRARY_PATH="${PX4CTRL_WS}/devel/lib:${PLANNER_WS}/devel/lib:${FASTLIO_WS}/devel/lib:${LIVOX_PLUGIN_WS}/devel/lib:${SUNRAY_WS}/devel/lib:${falcon_deps_usr_lib}:${falcon_deps_lib}:${falcon_deps_lib64}:/opt/ros/noetic/lib:${LD_LIBRARY_PATH:-}"
  else
    export LD_LIBRARY_PATH="${PX4CTRL_WS}/devel/lib:${planner_control_compat_devel:+${PLANNER_CONTROL_COMPAT_WS}/devel/lib:}${PLANNER_WS}/devel/lib:${FASTLIO_WS}/devel/lib:${LIVOX_PLUGIN_WS}/devel/lib:${SUNRAY_WS}/devel/lib:/opt/ros/noetic/lib:${LD_LIBRARY_PATH:-}"
  fi
}

resolve_ue_live_mirror_host() {
  if [[ "${UE_LIVE_MIRROR_HOST}" != "auto" ]]; then
    printf '%s\n' "${UE_LIVE_MIRROR_HOST}"
    return
  fi

  local gateway
  gateway="$(ip route 2>/dev/null | awk '/default/ {print $3; exit}' || true)"
  if [[ -n "${gateway}" ]]; then
    printf '%s\n' "${gateway}"
  else
    printf '127.0.0.1\n'
  fi
}

topic_file_name() {
  echo "$1" | sed 's#^/##; s#[^A-Za-z0-9_.-]#_#g'
}

sample_pointcloud_topic() {
  local topic="$1"
  local safe
  safe="$(topic_file_name "${topic}")"
  {
    echo "TOPIC ${topic}"
    echo "TYPE"
    timeout 5s rostopic type "${topic}" || true
    echo "INFO"
    timeout 5s rostopic info "${topic}" || true
    echo "SAMPLE"
    timeout 8s rostopic echo -n 1 --noarr "${topic}" || true
  } > "${RESULT_DIR}/topic_audit_${safe}.txt" 2>&1
}

start_fuel_compat_traj_server() {
  (
    set +u
    source /opt/ros/noetic/setup.bash
    source "${PX4CTRL_WS}/devel/setup.bash"
    source "${PLANNER_CONTROL_COMPAT_WS}/devel/setup.bash"
    set -u
    export CMAKE_PREFIX_PATH="${PX4CTRL_WS}/devel:${PLANNER_CONTROL_COMPAT_WS}/devel:/opt/ros/noetic:${CMAKE_PREFIX_PATH:-}"
    export ROS_PACKAGE_PATH="${PX4CTRL_WS}/src:${PLANNER_CONTROL_COMPAT_WS}/src:/opt/ros/noetic/share:${ROS_PACKAGE_PATH:-}"
    export PYTHONPATH="${PX4CTRL_WS}/devel/lib/python3/dist-packages:${PLANNER_CONTROL_COMPAT_WS}/devel/lib/python3/dist-packages:${PYTHONPATH:-}"
    export LD_LIBRARY_PATH="${PX4CTRL_WS}/devel/lib:${PLANNER_CONTROL_COMPAT_WS}/devel/lib:/opt/ros/noetic/lib:${LD_LIBRARY_PATH:-}"
    rosrun ego_planner traj_server \
      /position_cmd:="${FUEL_RAW_POSITION_CMD_TOPIC}" \
      ~planning/bspline:="${FUEL_TRAJ_UTILS_BSPLINE_TOPIC}" \
      _traj_server/time_forward:=0.5 \
      __name:=fuel_compat_traj_server \
      __ns:=/
  ) > "${RESULT_DIR}/fuel_compat_traj_server.log" 2>&1 &
  PIDS+=("$!")
}

start_fuel_native_traj_server() {
  (
    set +u
    source /opt/ros/noetic/setup.bash
    source "${PLANNER_WS}/devel/setup.bash"
    set -u
    export CMAKE_PREFIX_PATH="${PLANNER_WS}/devel:/opt/ros/noetic:${CMAKE_PREFIX_PATH:-}"
    export ROS_PACKAGE_PATH="${PLANNER_WS}/src:/opt/ros/noetic/share:${ROS_PACKAGE_PATH:-}"
    export PYTHONPATH="${PLANNER_WS}/devel/lib/python3/dist-packages:${PYTHONPATH:-}"
    export LD_LIBRARY_PATH="${PLANNER_WS}/devel/lib:/opt/ros/noetic/lib:${LD_LIBRARY_PATH:-}"
    rosrun plan_manage traj_server \
      /position_cmd:="${FUEL_NATIVE_POSITION_CMD_TOPIC}" \
      /odom_world:="${FUEL_EFFECTIVE_ODOM_TOPIC}" \
      _traj_server/pub_traj_id:=4 \
      _traj_server/init_x:="${FUEL_EFFECTIVE_INIT_X}" \
      _traj_server/init_y:="${FUEL_EFFECTIVE_INIT_Y}" \
      _traj_server/init_z:="${FUEL_EFFECTIVE_INIT_Z}" \
      _traj_server/align_start_time_to_receive:="${FUEL_ALIGN_TRAJ_START_TO_RECEIVE}" \
      _perception_utils/top_angle:="${FUEL_PERCEPTION_TOP_ANGLE_RAD}" \
      _perception_utils/left_angle:="${FUEL_PERCEPTION_LEFT_ANGLE_RAD}" \
      _perception_utils/right_angle:="${FUEL_PERCEPTION_RIGHT_ANGLE_RAD}" \
      _perception_utils/max_dist:="${FUEL_PERCEPTION_MAX_DIST_M}" \
      _perception_utils/vis_dist:="${FUEL_PERCEPTION_VIS_DIST_M}" \
      _perception_utils/omni_horizontal:="${FUEL_PERCEPTION_OMNI_HORIZONTAL}" \
      _fsm/replan_time:=0.1 \
      __name:=fuel_native_traj_server \
      __ns:=/
  ) > "${RESULT_DIR}/fuel_native_traj_server.log" 2>&1 &
  PIDS+=("$!")
}

discover_nonempty_pointcloud_topic() {
  local topic safe sample_file readiness_file
  rostopic list | sort > "${RESULT_DIR}/topic_list_before_goal4_nodes.txt" 2>/dev/null || true
  grep -Ei "livox|cloud|point|scan|imu|mavros|gazebo" "${RESULT_DIR}/topic_list_before_goal4_nodes.txt" \
    > "${RESULT_DIR}/topic_list_before_goal4_nodes_filtered.txt" 2>/dev/null || true

  for topic in ${RAW_LIDAR_TOPIC:-} ${RAW_LIDAR_TOPIC_CANDIDATES}; do
    [[ -n "${topic}" ]] || continue
    safe="$(topic_file_name "${topic}")"
    sample_file="${RESULT_DIR}/topic_audit_${safe}.txt"
    readiness_file="${RESULT_DIR}/raw_lidar_readiness_${safe}.json"
    if ! grep -Fxq "${topic}" "${RESULT_DIR}/topic_list_before_goal4_nodes.txt"; then
      sample_pointcloud_topic "${topic}"
      continue
    fi
    if python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_nonempty_pointcloud2.py" \
      --topic "${topic}" \
      --timeout-s "${RAW_LIDAR_READY_TIMEOUT_S}" \
      --output "${readiness_file}"; then
      sample_pointcloud_topic "${topic}"
      echo "${topic}"
      return 0
    fi
    sample_pointcloud_topic "${topic}"
  done
  return 1
}

FASTLIO_STACK_STARTED=false
FASTLIO_ALIGNMENT_STARTED=false
FASTLIO_MAVROS_ODOMETRY_STARTED=false
MAVROS_ODOM_BRIDGE_STARTED=false

start_mavros_local_odom_bridge() {
  if [[ "${MAVROS_ODOM_BRIDGE_STARTED}" == "true" ]]; then
    return
  fi
  if [[ "${MAVROS_ODOM_BRIDGE_MODE}" == "native" ]]; then
    echo "MAVROS_ODOM_BRIDGE_MODE=native; using existing /uav1/mavros/local_position/odom" \
      > "${RESULT_DIR}/odom_bridge.log"
    return
  fi
  if [[ "${MAVROS_ODOM_BRIDGE_MODE}" == "auto" ]]; then
    if python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /uav1/mavros/local_position/odom --timeout-s 5 --output "${RESULT_DIR}/native_odom_probe.txt" >/dev/null 2>&1; then
      echo "MAVROS_ODOM_BRIDGE_MODE=auto; native /uav1/mavros/local_position/odom is present, bridge not started" \
        > "${RESULT_DIR}/odom_bridge.log"
      return
    fi
  fi
  python3 "${PROJECT_ROOT}/Scripts/sunray/mavros_pose_velocity_to_odom_bridge.py" \
    --pose-topic /uav1/mavros/local_position/pose \
    --velocity-topic /uav1/mavros/local_position/velocity_local \
    --output-topic /uav1/mavros/local_position/odom \
    --frame-id world \
    --child-frame-id uav1/base_link \
    > "${RESULT_DIR}/odom_bridge.log" 2>&1 &
  PIDS+=("$!")
  MAVROS_ODOM_BRIDGE_STARTED=true
}

start_fastlio_stack() {
  if [[ "${FASTLIO_STACK_STARTED}" == "true" ]]; then
    return
  fi
  if [[ ! -f "${FASTLIO_SRC}/package.xml" || ! -f "${LIVOX_COMPAT_SRC}/package.xml" ]]; then
    echo "FAST-LIO authoritative source missing: ${FASTLIO_SRC} or ${LIVOX_COMPAT_SRC}" >&2
    exit 8
  fi

  # Reference reorganization can leave a stale Catkin devel tree with an empty
  # src directory. Rewire the authoritative project sources and incrementally
  # rebuild before treating the workspace as runtime-ready.
  mkdir -p "${FASTLIO_WS}/src"
  ln -sfn "${FASTLIO_SRC}" "${FASTLIO_WS}/src/FAST_LIO"
  ln -sfn "${LIVOX_COMPAT_SRC}" "${FASTLIO_WS}/src/livox_ros_driver_compat"
  (
    set +u
    source /opt/ros/noetic/setup.bash
    set -u
    cd "${FASTLIO_WS}"
    catkin_make --only-pkg-with-deps livox_ros_driver fast_lio
  ) > "${RESULT_DIR}/fastlio_build.log" 2>&1
  source_env
  rospack profile > "${RESULT_DIR}/fastlio_rospack_profile.log" 2>&1 || true

  local fastlio_package
  fastlio_package="$(rospack find fast_lio 2>/dev/null || true)"
  if [[ -z "${fastlio_package}" ]] \
    || ! rospack find livox_ros_driver >/dev/null 2>&1 \
    || ! rosmsg show livox_ros_driver/CustomMsg >/dev/null 2>&1 \
    || [[ ! -f "${fastlio_package}/launch/mapping_mosim_sunray_livox_custom.launch" ]]; then
    {
      echo "fast_lio_package=${fastlio_package}"
      rospack find livox_ros_driver 2>&1 || true
      rosmsg show livox_ros_driver/CustomMsg 2>&1 || true
      echo "expected_launch=${fastlio_package}/launch/mapping_mosim_sunray_livox_custom.launch"
    } > "${RESULT_DIR}/fastlio_package_audit.txt"
    echo "FAST-LIO package/CustomMsg/custom launch gate failed." >&2
    exit 8
  fi
  {
    echo "fast_lio_package=${fastlio_package}"
    echo "livox_ros_driver_package=$(rospack find livox_ros_driver)"
    echo "custom_msg=ready"
    echo "custom_launch=${fastlio_package}/launch/mapping_mosim_sunray_livox_custom.launch"
  } > "${RESULT_DIR}/fastlio_package_audit.txt"

  local deadline
  local livox_ready=false
  deadline=$((SECONDS + FASTLIO_SENSOR_START_TIMEOUT_S))
  while (( SECONDS < deadline )); do
    if python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /uav1/livox/lidar --timeout-s 5 --output "${RESULT_DIR}/livox_lidar_first.txt" &&
       python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /uav1/livox/imu --timeout-s 5 --output "${RESULT_DIR}/livox_imu_first.txt"; then
      livox_ready=true
      break
    fi
    sleep 2
  done

  if [[ "${livox_ready}" != "true" ]]; then
    echo "MID360 LiDAR/IMU did not publish before FAST-LIO startup timeout." >&2
    exit 8
  fi

  local fastlio_launch
  if [[ "${FASTLIO_MODE}" == "livox_custom" ]]; then
    python3 "${PROJECT_ROOT}/Scripts/sunray/pointcloud2_to_livox_custom_msg.py" \
      --input-topic /uav1/livox/lidar \
      --output-topic /mosim/fastlio/livox/lidar \
      --imu-topic /uav1/livox/imu \
      --stamp-source imu \
      --frame-id uav1/base_link \
      --scan-rate-hz "${FASTLIO_SCAN_RATE_HZ}" \
      --scan-lines 4 \
      --stride 1 \
      --points-per-scan-hint 20000 \
      --point-time-mode "${FASTLIO_CUSTOM_POINT_TIME_MODE}" \
      > "${RESULT_DIR}/pointcloud2_to_livox_custom.log" 2>&1 &
    PIDS+=("$!")
    sleep 2
    fastlio_launch="mapping_mosim_sunray_livox_custom.launch"
  elif [[ "${FASTLIO_MODE}" == "pointcloud2" ]]; then
    fastlio_launch="mapping_mosim_sunray_pointcloud2.launch"
  else
    echo "unsupported FASTLIO_MODE=${FASTLIO_MODE}" >&2
    exit 8
  fi

  roslaunch fast_lio "${fastlio_launch}" rviz:=false \
    filter_size_surf:="${FASTLIO_FILTER_SIZE_SURF}" \
    filter_size_map:="${FASTLIO_FILTER_SIZE_MAP}" \
    > "${RESULT_DIR}/fastlio_mapping.log" 2>&1 &
  PIDS+=("$!")

  python3 "${PROJECT_ROOT}/Scripts/ros/filter_pointcloud_by_z.py" \
    --input-topic /Laser_map \
    --output-topic /mosim/fastlio/laser_map_obstacles \
    --min-z "${FASTLIO_REVIEW_FILTER_MIN_Z}" \
    --max-z "${POINTCLOUD_MAX_WORLD_Z_M}" \
    --output-json "${RESULT_DIR}/fastlio_laser_map_obstacle_filter.json" \
    > "${RESULT_DIR}/fastlio_laser_map_obstacle_filter.log" 2>&1 &
  PIDS+=("$!")

  python3 "${PROJECT_ROOT}/Scripts/sunray/fastlio_uav_axes_marker_node.py" \
    --odom-topic "${FASTLIO_AXES_ODOM_TOPIC}" \
    --marker-topic "${FASTLIO_AXES_MARKER_TOPIC}" \
    --path-topic "${FASTLIO_AXES_PATH_TOPIC}" \
    --child-frame-id "${FASTLIO_AXES_CHILD_FRAME}" \
    --input-pose-frame "${FASTLIO_AXES_INPUT_POSE_FRAME}" \
    --mount-xyz "${FASTLIO_MOUNT_XYZ}" \
    --mount-rpy "${FASTLIO_MOUNT_RPY}" \
    > "${RESULT_DIR}/fastlio_uav_axes_marker_node.log" 2>&1 &
  PIDS+=("$!")

  # /path is published at a lower cadence than /Odometry and is not latched.
  # Subscribe before the odometry gate so the first path sample is not missed.
  local fastlio_ready=false
  local fastlio_path_wait_pid
  python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" \
    --topic /path \
    --timeout-s "${FASTLIO_PATH_START_TIMEOUT_S}" \
    --output "${RESULT_DIR}/fastlio_path_first_live.txt" &
  fastlio_path_wait_pid=$!
  PIDS+=("${fastlio_path_wait_pid}")
  deadline=$((SECONDS + FASTLIO_START_TIMEOUT_S))
  while (( SECONDS < deadline )); do
    if python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /Odometry --timeout-s 5 --output "${RESULT_DIR}/fastlio_odometry_first_live.txt"; then
      fastlio_ready=true
      break
    fi
    sleep 2
  done

  if [[ "${fastlio_ready}" != "true" && "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
    echo "FAST-LIO /Odometry did not publish before EKF fusion timeout." >&2
    exit 8
  fi
  if ! wait "${fastlio_path_wait_pid}"; then
    echo "FAST-LIO /path did not publish before FAST-LIO startup timeout." >&2
    exit 8
  fi

  (
    sleep 8
    {
      echo "TOPICS"
      rostopic list 2>/dev/null | grep -E "Laser_map|cloud_registered|Odometry|/path|livox|imu|fastlio/uav" || true
      echo "TYPES"
      for topic in /Laser_map /cloud_registered /Odometry /path "${FASTLIO_AXES_MARKER_TOPIC}" "${FASTLIO_AXES_PATH_TOPIC}" /mosim/fastlio/livox/lidar /uav1/livox/lidar /uav1/livox/imu; do
        printf "%s " "${topic}"
        timeout 5s rostopic type "${topic}" || true
      done
    } > "${RESULT_DIR}/fastlio_topic_summary_live.txt" 2>&1
    python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /Laser_map --timeout-s 12 --output "${RESULT_DIR}/fastlio_laser_map_first_live.txt" || true
    python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic /cloud_registered --timeout-s 12 --output "${RESULT_DIR}/fastlio_cloud_registered_first_live.txt" || true
    python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic "${FASTLIO_AXES_MARKER_TOPIC}" --timeout-s 12 --output "${RESULT_DIR}/fastlio_uav_axes_first_live.txt" || true
    timeout 12s rostopic hz /Laser_map -w 20 > "${RESULT_DIR}/fastlio_laser_map_hz_live.txt" 2>&1 || true
    timeout 12s rostopic hz /cloud_registered -w 20 > "${RESULT_DIR}/fastlio_cloud_registered_hz_live.txt" 2>&1 || true
  ) &
  PIDS+=("$!")

  FASTLIO_STACK_STARTED=true
}

start_fastlio_alignment_adapter() {
  if [[ "${FASTLIO_ALIGNMENT_STARTED}" == "true" ]]; then
    return
  fi
  start_mavros_local_odom_bridge
  start_fastlio_stack
  local republish_args=()
  if [[ "${FASTLIO_ALIGNMENT_REPUBLISH_LATEST}" == "true" ]]; then
    republish_args+=(--republish-latest)
  fi

  python3 "${PROJECT_ROOT}/Scripts/sunray/fastlio_odom_alignment_adapter.py" \
    --node-name mosim_fastlio_control_odom_alignment_adapter \
    --fastlio-topic /Odometry \
    --local-topic /uav1/mavros/local_position/odom \
    --output-topic "${FASTLIO_ALIGNED_ODOM_TOPIC}" \
    --path-topic "${FASTLIO_ALIGNED_PATH_TOPIC}" \
    --z-source "${FASTLIO_ALIGNMENT_Z_SOURCE}" \
    --truth-topic "${FASTLIO_ALIGNMENT_TRUTH_TOPIC}" \
    --alignment-reference "${FASTLIO_ALIGNMENT_REFERENCE}" \
    --alignment-origin-xyz "${FASTLIO_ALIGNMENT_ORIGIN_XYZ}" \
    --alignment-origin-rpy "${FASTLIO_ALIGNMENT_ORIGIN_RPY}" \
    --output-frame "${PX4CTRL_PATH_FRAME}" \
    --child-frame "base_link" \
    --stamp-source "${FASTLIO_ALIGNMENT_STAMP_SOURCE}" \
    --input-pose-frame "${FASTLIO_ODOM_INPUT_POSE_FRAME}" \
    --mount-xyz "${FASTLIO_MOUNT_XYZ}" \
    --mount-rpy "${FASTLIO_MOUNT_RPY}" \
    --dynamic-diagnostics-csv "${RESULT_DIR}/control_fastlio_dynamic_alignment.csv" \
    --dynamic-diagnostics-json "${RESULT_DIR}/control_fastlio_dynamic_alignment.json" \
    "${republish_args[@]}" \
    > "${RESULT_DIR}/fastlio_odom_alignment_adapter.log" 2>&1 &
  PIDS+=("$!")

  if python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" \
    --topic "${FASTLIO_ALIGNED_ODOM_TOPIC}" \
    --timeout-s "${ODOM_BRIDGE_READY_TIMEOUT_S}" \
    --output "${RESULT_DIR}/fastlio_aligned_odom_first.txt"; then
    FASTLIO_ALIGNMENT_STARTED=true
  fi

  if [[ "${FASTLIO_ALIGNMENT_STARTED}" != "true" ]]; then
    local required="${FASTLIO_ALIGNMENT_REQUIRED}"
    if [[ "${required}" == "auto" ]]; then
      if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
        required=true
      else
        required=false
      fi
    fi
    if [[ "${required}" == "true" ]]; then
      echo "No aligned FAST-LIO odometry on ${FASTLIO_ALIGNED_ODOM_TOPIC}; refusing to start PX4 ODOMETRY fusion." >&2
      exit 9
    fi
    echo "No aligned FAST-LIO odometry on ${FASTLIO_ALIGNED_ODOM_TOPIC}; continuing because FAST-LIO alignment is review-only for this run." \
      > "${RESULT_DIR}/fastlio_alignment_nonfatal_blocker.txt"
  fi
}

start_fastlio_mavros_odometry_adapter() {
  if [[ "${PX4CTRL_FASTLIO_ODOMETRY_FUSION_ENABLED}" != "true" || "${FASTLIO_MAVROS_ODOMETRY_STARTED}" == "true" ]]; then
    return
  fi
  start_fastlio_alignment_adapter
  python3 "${PROJECT_ROOT}/Scripts/sunray/fastlio_odom_to_mavros_odometry.py" \
    --node-name mosim_fastlio_control_mavros_odometry_adapter \
    --input-topic "${FASTLIO_ALIGNED_ODOM_TOPIC}" \
    --output-topic "${FASTLIO_MAVROS_ODOMETRY_TOPIC}" \
    --expected-input-frame "${PX4CTRL_PATH_FRAME}" \
    --output-frame odom \
    --output-child-frame base_link \
    --input-twist-frame world \
    --max-age-s "${FASTLIO_MAVROS_ODOMETRY_MAX_AGE_S}" \
    --max-future-s "${FASTLIO_MAVROS_ODOMETRY_MAX_FUTURE_S}" \
    --position-stddev-m "${FASTLIO_MAVROS_ODOMETRY_POSITION_STDDEV_M}" \
    --orientation-stddev-rad "${FASTLIO_MAVROS_ODOMETRY_ORIENTATION_STDDEV_RAD}" \
    --velocity-stddev-mps "${FASTLIO_MAVROS_ODOMETRY_VELOCITY_STDDEV_MPS}" \
    --diagnostics-json "${RESULT_DIR}/fastlio_mavros_odometry_adapter.json" \
    --events-jsonl "${RESULT_DIR}/fastlio_mavros_odometry_events.jsonl" \
    > "${RESULT_DIR}/fastlio_mavros_odometry_adapter.log" 2>&1 &
  PIDS+=("$!")

  if ! python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" \
    --topic "${FASTLIO_MAVROS_ODOMETRY_TOPIC}" \
    --timeout-s "${ODOM_BRIDGE_READY_TIMEOUT_S}" \
    --output "${RESULT_DIR}/fastlio_mavros_odometry_first.txt"; then
    echo "No unified FAST-LIO odometry reached ${FASTLIO_MAVROS_ODOMETRY_TOPIC}" >&2
    exit 10
  fi

  {
    echo "TOPIC_INFO"
    rostopic info "${FASTLIO_MAVROS_ODOMETRY_TOPIC}" || true
    echo "MAVROS_NODE_INFO"
    rosnode info /uav1/mavros || true
    echo "PLUGIN_LIST_PARAMS"
    rosparam get /uav1/mavros/plugin_blacklist || true
    rosparam get /uav1/mavros/plugin_whitelist || true
    echo "MAVROS_PLUGIN_LOG"
    grep -E "Plugin odom|odometry/out" "${RESULT_DIR}/sunray_px4_basic.log" || true
  } > "${RESULT_DIR}/mavros_odometry_plugin_audit.txt" 2>&1
  if ! grep -Eq '^[[:space:]]*\*[[:space:]]+/uav1/mavros[[:space:]]' "${RESULT_DIR}/mavros_odometry_plugin_audit.txt"; then
    echo "MAVROS odom plugin is not subscribed to ${FASTLIO_MAVROS_ODOMETRY_TOPIC}" >&2
    exit 10
  fi
  FASTLIO_MAVROS_ODOMETRY_STARTED=true
}

configure_mavros_stream_rates() {
  local rate_hz="$1"
  if [[ "${rate_hz}" == "0" || "${rate_hz}" == "0.0" ]]; then
    return
  fi
  {
    echo "MAVROS_STREAM_RATE_HZ=${rate_hz}"
    echo "MAVROS_SET_STREAM_GROUPS=${MAVROS_SET_STREAM_GROUPS}"
    for group in ${MAVROS_SET_STREAM_GROUPS}; do
      case "${group}" in
        raw_sensors) stream_id=1 ;;
        position) stream_id=6 ;;
        extra1) stream_id=10 ;;
        extra2) stream_id=11 ;;
        *) echo "skip_unknown_stream_group ${group}"; continue ;;
      esac
      echo "set_stream_rate ${group}(${stream_id}) ${rate_hz}Hz"
      timeout 8s rosservice call /uav1/mavros/set_stream_rate "stream_id: ${stream_id}
message_rate: ${rate_hz}
on_off: true" || true
    done
    if [[ "${MAVROS_SET_MESSAGE_INTERVALS}" == "true" ]]; then
      local interval_us
      interval_us="$(python3 - <<PY
rate = float("${rate_hz}")
print(int(round(1000000.0 / rate)))
PY
)"
      echo "MAVROS_SET_MESSAGE_IDS=${MAVROS_SET_MESSAGE_IDS}"
      for spec in ${MAVROS_SET_MESSAGE_IDS}; do
        local msg_id msg_name
        msg_id="${spec%%:*}"
        msg_name="${spec#*:}"
        echo "set_message_interval ${msg_name}(${msg_id}) ${interval_us}us"
        timeout 8s rosservice call /uav1/mavros/cmd/command "broadcast: false
command: 511
confirmation: 0
param1: ${msg_id}
param2: ${interval_us}
param3: 0
param4: 0
param5: 0
param6: 0
param7: 0" || true
      done
    fi
  } > "${RESULT_DIR}/mavros_stream_rate_request.txt" 2>&1
}

apply_px4_int_param_override() {
  local param_id="$1"
  local value="$2"
  if [[ -z "${value}" ]]; then
    return 0
  fi
  {
    echo "PARAM_OVERRIDE ${param_id}=${value}"
    # EKF2 boot values are injected through px4-rc.params before EKF2 starts.
    # Refresh MAVROS first so a matching boot value does not require a
    # redundant post-boot param/set service call.
    if [[ "${PX4CTRL_PARAM_CACHE_REFRESHED:-false}" != "true" ]]; then
      echo "PARAM_PULL_BEFORE_VERIFY"
      if ! timeout 30s rosservice call /uav1/mavros/param/pull "force_pull: true"; then
        echo "PARAM_PULL_FAILED before ${param_id}" >&2
        return 1
      fi
      PX4CTRL_PARAM_CACHE_REFRESHED=true
    else
      echo "PARAM_PULL_SKIPPED_CACHE_REFRESHED"
    fi
    local verify_output=""
    local verify_attempt
    for verify_attempt in 1 2 3; do
      echo "PARAM_VERIFY_BOOT_SERVICE ${param_id} attempt=${verify_attempt}"
      if verify_output="$(timeout 5s rosservice call /uav1/mavros/param/get "param_id: '${param_id}'" 2>&1)"; then
        printf '%s\n' "${verify_output}"
        if printf '%s\n' "${verify_output}" | grep -Eq "integer: ${value}([[:space:]]|$)"; then
          echo "PARAM_BOOT_VALUE_VERIFIED ${param_id}=${value}"
          return 0
        fi
      else
        printf '%s\n' "${verify_output}"
      fi
      if (( verify_attempt < 3 )); then
        sleep 1
      fi
    done
    echo "PARAM_BOOT_VALUE_MISMATCH ${param_id}: expected=${value}"
    echo "PARAM_SET_SERVICE ${param_id}=${value}"
    if ! timeout 8s rosservice call /uav1/mavros/param/set "param_id: '${param_id}'
value:
  integer: ${value}
  real: 0.0"; then
      echo "PARAM_SET_FAILED ${param_id}=${value}" >&2
      return 1
    fi
    for verify_attempt in 1 2 3; do
      echo "PARAM_VERIFY_SERVICE ${param_id} attempt=${verify_attempt}"
      if verify_output="$(timeout 5s rosservice call /uav1/mavros/param/get "param_id: '${param_id}'" 2>&1)"; then
        printf '%s\n' "${verify_output}"
        if printf '%s\n' "${verify_output}" | grep -Eq "integer: ${value}([[:space:]]|$)"; then
          return 0
        fi
      else
        printf '%s\n' "${verify_output}"
      fi
      if (( verify_attempt < 3 )); then
        sleep 1
      fi
    done
    echo "PARAM_VERIFY_MISMATCH ${param_id}: expected=${value}" >&2
    return 1
  } >> "${RESULT_DIR}/px4_param_overrides.txt" 2>&1
}

apply_px4_param_override() {
  local param_id="$1"
  local value="$2"
  if [[ -z "${param_id}" || -z "${value}" ]]; then
    return 0
  fi
  local integer_value="0"
  local real_value="0.0"
  if [[ "${value}" =~ ^-?[0-9]+$ ]]; then
    integer_value="${value}"
  else
    real_value="${value}"
  fi
  {
    echo "PARAM_OVERRIDE ${param_id}=${value}"
    if [[ "${PX4CTRL_PARAM_PULL_BEFORE_OVERRIDE}" == "true" ]]; then
      echo "PARAM_PULL_BEFORE_OVERRIDE"
      timeout 15s rosservice call /uav1/mavros/param/pull "force_pull: true" || true
    fi
    echo "PARAM_SET_SERVICE ${param_id}=${value}"
    timeout 8s rosservice call /uav1/mavros/param/set "param_id: '${param_id}'
value:
  integer: ${integer_value}
  real: ${real_value}" || true
    echo "PARAM_VERIFY_SERVICE ${param_id}"
    timeout 5s rosservice call /uav1/mavros/param/get "param_id: '${param_id}'" || true
  } >> "${RESULT_DIR}/px4_param_overrides.txt" 2>&1
}

if [[ ! -d "${PX4CTRL_WS}/devel" ]]; then
  echo "PX4CTRL_WS devel missing: ${PX4CTRL_WS}/devel" >&2
  exit 2
fi
if [[ ! -d "${PLANNER_WS}/devel" ]]; then
  echo "Planner workspace devel missing: ${PLANNER_WS}/devel; run the matching setup_goal4_ego*_overlay.sh" >&2
  exit 2
fi
if [[ ! -f "${LIVOX_PLUGIN_WS}/devel/lib/liblivox_laser_simulation.so" ]]; then
  LOG_PATH="${RESULT_DIR}/sunray_livox_plugin_build.log" \
    SUNRAY_WS="${SUNRAY_WS}" \
    LIVOX_PLUGIN_WS="${LIVOX_PLUGIN_WS}" \
    bash "${PROJECT_ROOT}/Scripts/sunray/setup_sunray_livox_gazebo_plugin.sh" \
    > "${RESULT_DIR}/sunray_livox_plugin_setup_stdout.txt" 2>&1
fi

if [[ "${SUNRAY_FACTORY_WORLD_RUNTIME_OVERLAY}" == "true" ]]; then
  if [[ "${SUNRAY_GAZEBO_LAUNCH_FILE}" != *"factory_l2_sunray_px4_gazebo.launch"* ]]; then
    echo "Factory world runtime overlay requires factory_l2_sunray_px4_gazebo.launch" >&2
    exit 2
  fi
  RUNTIME_WORLD_FILE="${RESULT_DIR}/factory_world_runtime_overlay.sdf"
  python3 "${PROJECT_ROOT}/Scripts/sunray/materialize_gazebo_world_overlay.py" \
    --project-root "${PROJECT_ROOT}" \
    --source "${WORLD_FILE}" \
    --output "${RUNTIME_WORLD_FILE}" \
    --manifest "${RESULT_DIR}/factory_world_runtime_overlay.json" \
    --max-step-size-s "${SUNRAY_GAZEBO_MAX_STEP_SIZE_S}" \
    --real-time-update-rate-hz "${SUNRAY_GAZEBO_REAL_TIME_UPDATE_RATE_HZ}" \
    > "${RESULT_DIR}/factory_world_runtime_overlay.log"
  WORLD_FILE="${RUNTIME_WORLD_FILE}"
fi

cleanup force
sleep 3
PX4_ULOG_CAPTURE_AFTER_EPOCH="$(date +%s)"
prepare_px4_ros1_runtime_overlay
source_env
sync_mavros_plugin_config

{
  echo "ROS_ENV_SNAPSHOT"
  env | grep -E '^(ROS_PACKAGE_PATH|PYTHONPATH|CMAKE_PREFIX_PATH|LD_LIBRARY_PATH)=' || true
  rospack profile || true
  REQUIRED_PACKAGES=(px4ctrl quadrotor_msgs traj_utils plan_env sunray_msgs)
  if [[ "${PLANNER_VARIANT}" == "diff_planner" ]]; then
    REQUIRED_PACKAGES+=(diff_planner multipoint)
  elif [[ "${PLANNER_VARIANT}" == "fuel" || "${PLANNER_VARIANT}" == "racer" ]]; then
    REQUIRED_PACKAGES+=(exploration_manager plan_manage bspline lkh_tsp_solver)
  elif [[ "${PLANNER_VARIANT}" == "falcon" ]]; then
    REQUIRED_PACKAGES+=(exploration_manager voxel_mapping pathfinding fast_planner exploration_preprocessing exploration_utils trajectory)
  elif [[ "${PLANNER_VARIANT}" == "uav_frontier" ]]; then
    REQUIRED_PACKAGES+=(uav_frontier_exploration_3d octomap_ros octomap_msgs mean_shift_clustering)
  elif [[ "${PLANNER_VARIANT}" == "highstar" ]]; then
    REQUIRED_PACKAGES+=(murder block_map swarm_exp_msgs)
  else
    REQUIRED_PACKAGES+=(ego_planner)
  fi
  for pkg in "${REQUIRED_PACKAGES[@]}"; do
    echo "rospack find ${pkg}"
    rospack find "${pkg}"
  done
  if [[ "${PLANNER_VARIANT}" == "fuel" || "${PLANNER_VARIANT}" == "racer" ]]; then
    python3 -c "import sunray_msgs.msg, quadrotor_msgs.msg, bspline.msg; print('python message imports ok')"
  elif [[ "${PLANNER_VARIANT}" == "falcon" ]]; then
    python3 -c "import sunray_msgs.msg, quadrotor_msgs.msg, trajectory.msg; print('python message imports ok')"
  elif [[ "${PLANNER_VARIANT}" == "uav_frontier" ]]; then
    python3 -c "import sunray_msgs.msg, quadrotor_msgs.msg, octomap_msgs.msg; print('python message imports ok')"
  elif [[ "${PLANNER_VARIANT}" == "highstar" ]]; then
    python3 -c "import sunray_msgs.msg, quadrotor_msgs.msg, swarm_exp_msgs.msg; print('python message imports ok')"
  else
    python3 -c "import sunray_msgs.msg, quadrotor_msgs.msg, traj_utils.msg; print('python message imports ok')"
  fi
} > "${RESULT_DIR}/ros_env_snapshot.txt" 2>&1 || {
  echo "ROS environment missing required Goal4 packages; see ${RESULT_DIR}/ros_env_snapshot.txt" >&2
  exit 6
}

export SUNRAY_GAZEBO_MAX_STEP_SIZE_S
export SUNRAY_GAZEBO_REAL_TIME_UPDATE_RATE_HZ

python3 "${PROJECT_ROOT}/Scripts/sunray/sync_assembled_model_into_sunray_ros1.py" \
  --project-root "${PROJECT_ROOT}" \
  --sunray-ws "${SUNRAY_WS}" \
  --manifest "${RESULT_DIR}/assembled_model_sync.json" \
  > "${RESULT_DIR}/assembled_model_sync.log" 2>&1

rm -f /tmp/px4-sock-0 /tmp/px4-sock-1 2>/dev/null || true

if [[ "${SUNRAY_SPLIT_WORLD_BASIC_LAUNCH}" == "true" ]]; then
  roslaunch gazebo_ros empty_world.launch \
    gui:="${GUI}" world_name:="${WORLD_FILE}" debug:=false verbose:=false paused:=false use_sim_time:="${USE_SIM_TIME}" \
    > "${RESULT_DIR}/sunray_gazebo_world.log" 2>&1 &
  PIDS+=("$!")
  echo "${PIDS[-1]}" > "${RESULT_DIR}/sunray_gazebo_world.pid"
  sleep 8

  # A split world launch already owns the ROS Master's run_id.  Reuse it for
  # the model/PX4 launch; otherwise roslaunch rejects the second launch before
  # spawn_model can create uav1.
  ROS_MASTER_RUN_ID=""
  run_id_deadline=$((SECONDS + 30))
  while (( SECONDS < run_id_deadline )); do
    ROS_MASTER_RUN_ID="$(rosparam get /run_id 2>/dev/null | tr -d '\r\n')"
    [[ -n "${ROS_MASTER_RUN_ID}" ]] && break
    sleep 1
  done
  if [[ -z "${ROS_MASTER_RUN_ID}" ]]; then
    echo "ROS Master run_id is unavailable after Gazebo world startup" >&2
    timeout 5s rosnode list >&2 || true
    exit 3
  fi

  roslaunch --run_id "${ROS_MASTER_RUN_ID}" sunray_simulator sunray_px4_basic.launch \
    uav_id:=1 vehicle:="${VEHICLE}" \
    uav_init_x:="${SUNRAY_UAV_INIT_X}" uav_init_y:="${SUNRAY_UAV_INIT_Y}" \
    uav_init_z:="${SUNRAY_UAV_INIT_Z}" uav_init_yaw:="${SUNRAY_UAV_INIT_YAW}" \
    > "${RESULT_DIR}/sunray_px4_basic.log" 2>&1 &
  PIDS+=("$!")
  echo "${PIDS[-1]}" > "${RESULT_DIR}/sunray_px4_basic.pid"
elif [[ "${SUNRAY_GAZEBO_LAUNCH_FILE}" == *"sunray_sim_uav_planning.launch" ]]; then
  roslaunch "${SUNRAY_GAZEBO_LAUNCH_FILE}" \
    gui:="${GUI}" rviz_enable:=false world:="${WORLD_FILE}" use_sim_time:="${USE_SIM_TIME}" \
    uav_id:=1 vehicle:="${VEHICLE}" \
    uav_init_x:="${SUNRAY_UAV_INIT_X}" uav_init_y:="${SUNRAY_UAV_INIT_Y}" \
    uav_init_yaw:="${SUNRAY_UAV_INIT_YAW}" \
    > "${RESULT_DIR}/sunray_gazebo.log" 2>&1 &
  PIDS+=("$!")
  echo "${PIDS[-1]}" > "${RESULT_DIR}/sunray_gazebo.pid"
else
  roslaunch "${SUNRAY_GAZEBO_LAUNCH_FILE}" \
    uav_num:=1 vehicle:="${VEHICLE}" gui:="${GUI}" world:="${WORLD_FILE}" use_sim_time:="${USE_SIM_TIME}" \
    uav1_init_x:="${SUNRAY_UAV_INIT_X}" uav1_init_y:="${SUNRAY_UAV_INIT_Y}" \
    uav1_init_z:="${SUNRAY_UAV_INIT_Z}" uav1_init_yaw:="${SUNRAY_UAV_INIT_YAW}" \
    > "${RESULT_DIR}/sunray_gazebo.log" 2>&1 &
  PIDS+=("$!")
  echo "${PIDS[-1]}" > "${RESULT_DIR}/sunray_gazebo.pid"
fi

if ! kill -0 "${PIDS[0]}" >/dev/null 2>&1; then
  echo "sunray gazebo launch exited before MAVROS ready" >&2
  exit 3
fi

if ! python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_gazebo_model.py" \
  --model uav1 \
  --timeout-s "${GAZEBO_MODEL_READY_TIMEOUT_S}" \
  --output "${RESULT_DIR}/gazebo_model_uav1_first.txt"; then
  echo "Gazebo did not report uav1 before model-ready timeout" >&2
  exit 3
fi

if ! python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_mavros_state.py" \
  --topic /uav1/mavros/state \
  --timeout-s "${MAVROS_READY_TIMEOUT_S}" \
  --output "${RESULT_DIR}/mavros_state_first.txt"; then
  echo "MAVROS did not connect" >&2
  exit 4
fi

configure_mavros_stream_rates "${MAVROS_STREAM_RATE_HZ}"

{
  echo "PX4CTRL_EKF2_EV_CTRL_OVERRIDE=${PX4CTRL_EKF2_EV_CTRL_OVERRIDE:-none}"
  echo "PX4CTRL_EKF2_HGT_REF_OVERRIDE=${PX4CTRL_EKF2_HGT_REF_OVERRIDE:-none}"
} > "${RESULT_DIR}/px4_param_overrides.txt"
if ! apply_px4_int_param_override EKF2_EV_CTRL "${PX4CTRL_EKF2_EV_CTRL_OVERRIDE}"; then
  echo "Required PX4 external-vision parameter EKF2_EV_CTRL was not applied and verified" >&2
  exit 6
fi
if ! apply_px4_int_param_override EKF2_HGT_REF "${PX4CTRL_EKF2_HGT_REF_OVERRIDE}"; then
  echo "Required PX4 external-vision parameter EKF2_HGT_REF was not applied and verified" >&2
  exit 6
fi
if [[ -n "${PX4CTRL_EXTRA_PARAM_OVERRIDES}" ]]; then
  for param_pair in ${PX4CTRL_EXTRA_PARAM_OVERRIDES//,/ }; do
    if [[ "${param_pair}" != *=* ]]; then
      echo "Skipping malformed PX4CTRL_EXTRA_PARAM_OVERRIDES item: ${param_pair}" >> "${RESULT_DIR}/px4_param_overrides.txt"
      continue
    fi
    apply_px4_param_override "${param_pair%%=*}" "${param_pair#*=}" || true
  done
fi

if [[ "${PX4CTRL_START_EXTERNAL_FUSION}" == "true" ]]; then
  EXTERNAL_FUSION_SOURCE_EFFECTIVE=2
  EXTERNAL_FUSION_POSITION_TOPIC_EFFECTIVE=/uav1/mavros/local_position/pose
  external_fusion_node_bin="${SUNRAY_WS}/devel/lib/sunray_uav_control/external_fusion_node"
  if [[ ! -x "${external_fusion_node_bin}" ]]; then
    echo "external_fusion node missing or not executable: ${external_fusion_node_bin}" >&2
    exit 2
  fi
  "${external_fusion_node_bin}" \
    __name:=external_fusion \
    _uav_id:=1 \
    _uav_name:=uav \
    _external_source:="${EXTERNAL_FUSION_SOURCE_EFFECTIVE}" \
    _position_topic:="${EXTERNAL_FUSION_POSITION_TOPIC_EFFECTIVE}" \
    _use_vision_pose:="${PX4CTRL_EXTERNAL_FUSION_USE_VISION_POSE}" \
    > "${RESULT_DIR}/external_fusion.log" 2>&1 &
  PIDS+=("$!")
  sleep 3
  {
    echo "external_fusion_node_bin=${external_fusion_node_bin}"
    echo "external_fusion_source_effective=${EXTERNAL_FUSION_SOURCE_EFFECTIVE}"
    echo "external_fusion_position_topic_effective=${EXTERNAL_FUSION_POSITION_TOPIC_EFFECTIVE}"
    pgrep -af "external_fusion_node" || true
  } > "${RESULT_DIR}/external_fusion_process.txt"
else
  EXTERNAL_FUSION_SOURCE_EFFECTIVE=none
  EXTERNAL_FUSION_POSITION_TOPIC_EFFECTIVE=none
  echo "PX4CTRL_START_EXTERNAL_FUSION=false; external_fusion disabled for this planner run" \
    > "${RESULT_DIR}/external_fusion.log"
fi

if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
  start_fastlio_alignment_adapter
  start_fastlio_mavros_odometry_adapter
  echo "PX4CTRL_ENABLE_FASTLIO_EKF_FUSION=true; synchronized FAST-LIO pose/velocity enters PX4 EKF through MAVLink ODOMETRY on ${FASTLIO_MAVROS_ODOMETRY_TOPIC}; split external_fusion/vision_speed disabled; px4ctrl remains on /uav1/mavros/local_position/odom" \
    > "${RESULT_DIR}/odom_source.log"
else
  start_mavros_local_odom_bridge
fi

if ! python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" \
  --topic /uav1/mavros/local_position/odom \
  --timeout-s "${ODOM_BRIDGE_READY_TIMEOUT_S}" \
  --output "${RESULT_DIR}/odom_first.txt"; then
  echo "No odometry on /uav1/mavros/local_position/odom" >&2
  exit 5
fi

if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
  {
    echo "PX4 PARAM SNAPSHOT"
    for param in \
      EKF2_HGT_REF EKF2_AID_MASK EKF2_EV_CTRL EKF2_EV_POS_X EKF2_EV_POS_Y EKF2_EV_POS_Z \
      EKF2_EV_DELAY EKF2_EV_NOISE EKF2_EV_NOISE_MD EKF2_EVP_NOISE EKF2_EVV_NOISE EKF2_EVA_NOISE EKF2_REQ_EPH EKF2_REQ_EPV
    do
      printf "%s\n" "${param}"
      timeout 5s rosservice call /uav1/mavros/param/get "param_id: '${param}'" 2>&1 || true
    done
  } > "${RESULT_DIR}/px4_param_snapshot_before_mission.txt" 2>&1 &
  PIDS+=("$!")
fi

if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" && "${CONTROL_FUSION_DIAGNOSTICS_ENABLED}" == "true" ]]; then
  python3 "${PROJECT_ROOT}/Scripts/sunray/record_sunray_ros1_control_diagnostics.py" \
    --out-dir "${RESULT_DIR}/control_fusion_diagnostics" \
    --duration-s "${CONTROL_FUSION_DIAGNOSTICS_DURATION_S}" \
    --sample-rate-hz "${CONTROL_FUSION_DIAGNOSTICS_RATE_HZ}" \
    --uav-ns /uav1 \
    --truth-model-name uav1 \
    --fastlio-odom-topic /Odometry \
    --fastlio-aligned-odom-topic "${FASTLIO_ALIGNED_ODOM_TOPIC}" \
    > "${RESULT_DIR}/control_fusion_diagnostics.log" 2>&1 &
  PIDS+=("$!")
fi

if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
  (
    sleep 8
    for topic in "${FASTLIO_ALIGNED_ODOM_TOPIC}" "${FASTLIO_MAVROS_ODOMETRY_TOPIC}" /uav1/mavros/local_position/odom /uav1/mavros/imu/data; do
      safe="$(topic_file_name "${topic}")"
      timeout 10s rostopic hz "${topic}" -w 20 > "${RESULT_DIR}/hz_${safe}.txt" 2>&1 || true
      python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" --topic "${topic}" --timeout-s 8 --output "${RESULT_DIR}/first_${safe}.txt" || true
    done
  ) &
  PIDS+=("$!")
  (
    sleep 8
    timeout "${TOTAL_TIMEOUT_S}s" rostopic echo /uav1/mavros/estimator_status \
      > "${RESULT_DIR}/mavros_estimator_status.log" 2>&1 || true
  ) &
  PIDS+=("$!")
fi

if [[ ! -s "${RESULT_DIR}/odom_first.txt" ]]; then
  echo "No odometry on /uav1/mavros/local_position/odom" >&2
  exit 5
fi

if ! DISCOVERED_RAW_LIDAR_TOPIC="$(discover_nonempty_pointcloud_topic)"; then
  echo "No nonempty raw MID360 PointCloud2 topic found; see ${RESULT_DIR}/topic_list_before_goal4_nodes*.txt and topic_audit_*.txt" >&2
  exit 7
fi
RAW_LIDAR_TOPIC="${DISCOVERED_RAW_LIDAR_TOPIC}"
echo "${RAW_LIDAR_TOPIC}" > "${RESULT_DIR}/raw_lidar_topic_selected.txt"

PX4CTRL_LAUNCH="${RESULT_DIR}/px4ctrl_mosim.launch"
PX4CTRL_CONFIG="$(rospack find px4ctrl)/config/ctrl_param_fpv.yaml"
cat > "${PX4CTRL_LAUNCH}" <<EOF
<launch>
  <node pkg="px4ctrl" type="px4ctrl_node" name="px4ctrl" output="screen">
    <remap from="~odom" to="/uav1/mavros/local_position/odom" />
    <remap from="~cmd" to="/position_cmd" />
    <remap from="/mavros/state" to="/uav1/mavros/state" />
    <remap from="/mavros/extended_state" to="/uav1/mavros/extended_state" />
    <remap from="/mavros/imu/data" to="/uav1/mavros/imu/data" />
    <remap from="/mavros/rc/in" to="/uav1/mavros/rc/in" />
    <remap from="/mavros/battery" to="/uav1/mavros/battery" />
    <remap from="/mavros/setpoint_raw/attitude" to="/uav1/mavros/setpoint_raw/attitude" />
    <remap from="/mavros/set_mode" to="/uav1/mavros/set_mode" />
    <remap from="/mavros/cmd/arming" to="/uav1/mavros/cmd/arming" />
    <remap from="/mavros/cmd/command" to="/uav1/mavros/cmd/command" />
    <rosparam command="load" file="${PX4CTRL_CONFIG}" />
    <param name="mass" value="${PX4CTRL_MASS}" />
    <param name="ctrl_freq_max" value="${PX4CTRL_CTRL_FREQ_MAX}" />
    <param name="use_bodyrate_ctrl" value="${PX4CTRL_USE_BODYRATE_CTRL}" />
    <param name="odom_velocity_frame" value="${PX4CTRL_ODOM_VELOCITY_FRAME}" />
    <param name="mosim_generated_core_mode" value="${PX4CTRL_CORE_PROFILE}" />
    <param name="auto_takeoff_land/enable" value="true" />
    <param name="auto_takeoff_land/enable_auto_arm" value="true" />
    <param name="auto_takeoff_land/no_RC" value="true" />
    <param name="auto_takeoff_land/takeoff_height" value="${PX4CTRL_AUTO_TAKEOFF_HEIGHT}" />
    <param name="auto_takeoff_land/takeoff_land_speed" value="${PX4CTRL_AUTO_TAKEOFF_SPEED}" />
    <param name="thrust_model/hover_percentage" value="${PX4CTRL_HOVER_PERCENTAGE}" />
    <param name="thrust_model/estimate_enable" value="${PX4CTRL_THRUST_ESTIMATE_ENABLE}" />
    <param name="gain/Kp0" value="${PX4CTRL_KP_XY}" />
    <param name="gain/Kp1" value="${PX4CTRL_KP_XY}" />
    <param name="gain/Kp2" value="${PX4CTRL_KP_Z}" />
    <param name="gain/Kv0" value="${PX4CTRL_KV_XY}" />
    <param name="gain/Kv1" value="${PX4CTRL_KV_XY}" />
    <param name="gain/Kv2" value="${PX4CTRL_KV_Z}" />
    <param name="smc/lambda_x" value="${PX4CTRL_SMC_LAMBDA_XY}" />
    <param name="smc/lambda_y" value="${PX4CTRL_SMC_LAMBDA_XY}" />
    <param name="smc/lambda_z" value="${PX4CTRL_SMC_LAMBDA_Z}" />
    <param name="smc/eta_x" value="${PX4CTRL_SMC_ETA_XY}" />
    <param name="smc/eta_y" value="${PX4CTRL_SMC_ETA_XY}" />
    <param name="smc/eta_z" value="${PX4CTRL_SMC_ETA_Z}" />
    <param name="smc/phi_x" value="${PX4CTRL_SMC_PHI_XY}" />
    <param name="smc/phi_y" value="${PX4CTRL_SMC_PHI_XY}" />
    <param name="smc/phi_z" value="${PX4CTRL_SMC_PHI_Z}" />
    <param name="smc/surface_limit_x" value="${PX4CTRL_SMC_SURFACE_LIMIT_XY}" />
    <param name="smc/surface_limit_y" value="${PX4CTRL_SMC_SURFACE_LIMIT_XY}" />
    <param name="smc/surface_limit_z" value="${PX4CTRL_SMC_SURFACE_LIMIT_Z}" />
    <param name="indi/gain_x" value="${PX4CTRL_INDI_GAIN_XY}" />
    <param name="indi/gain_y" value="${PX4CTRL_INDI_GAIN_XY}" />
    <param name="indi/gain_z" value="${PX4CTRL_INDI_GAIN_Z}" />
    <param name="indi/increment_limit_x" value="${PX4CTRL_INDI_INCREMENT_LIMIT_XY}" />
    <param name="indi/increment_limit_y" value="${PX4CTRL_INDI_INCREMENT_LIMIT_XY}" />
    <param name="indi/increment_limit_z" value="${PX4CTRL_INDI_INCREMENT_LIMIT_Z}" />
    <param name="indi/measured_accel_limit_x" value="${PX4CTRL_INDI_MEASURED_ACCEL_LIMIT_XY}" />
    <param name="indi/measured_accel_limit_y" value="${PX4CTRL_INDI_MEASURED_ACCEL_LIMIT_XY}" />
    <param name="indi/measured_accel_limit_z" value="${PX4CTRL_INDI_MEASURED_ACCEL_LIMIT_Z}" />
    <param name="indi/accel_lpf_alpha" value="${PX4CTRL_INDI_ACCEL_LPF_ALPHA}" />
    <param name="nmpc/horizon_s" value="${PX4CTRL_NMPC_HORIZON_S}" />
    <param name="nmpc/position_weight_x" value="${PX4CTRL_NMPC_POSITION_WEIGHT_XY}" />
    <param name="nmpc/position_weight_y" value="${PX4CTRL_NMPC_POSITION_WEIGHT_XY}" />
    <param name="nmpc/position_weight_z" value="${PX4CTRL_NMPC_POSITION_WEIGHT_Z}" />
    <param name="nmpc/velocity_weight_x" value="${PX4CTRL_NMPC_VELOCITY_WEIGHT_XY}" />
    <param name="nmpc/velocity_weight_y" value="${PX4CTRL_NMPC_VELOCITY_WEIGHT_XY}" />
    <param name="nmpc/velocity_weight_z" value="${PX4CTRL_NMPC_VELOCITY_WEIGHT_Z}" />
    <param name="nmpc/control_weight_x" value="${PX4CTRL_NMPC_CONTROL_WEIGHT_XY}" />
    <param name="nmpc/control_weight_y" value="${PX4CTRL_NMPC_CONTROL_WEIGHT_XY}" />
    <param name="nmpc/control_weight_z" value="${PX4CTRL_NMPC_CONTROL_WEIGHT_Z}" />
    <param name="nmpc/accel_limit_x" value="${PX4CTRL_NMPC_ACCEL_LIMIT_XY}" />
    <param name="nmpc/accel_limit_y" value="${PX4CTRL_NMPC_ACCEL_LIMIT_XY}" />
    <param name="nmpc/accel_limit_z" value="${PX4CTRL_NMPC_ACCEL_LIMIT_Z}" />
    <param name="nmpc/increment_limit_x" value="${PX4CTRL_NMPC_INCREMENT_LIMIT_XY}" />
    <param name="nmpc/increment_limit_y" value="${PX4CTRL_NMPC_INCREMENT_LIMIT_XY}" />
    <param name="nmpc/increment_limit_z" value="${PX4CTRL_NMPC_INCREMENT_LIMIT_Z}" />
  </node>
</launch>
EOF

roslaunch "${PX4CTRL_LAUNCH}" > "${RESULT_DIR}/px4ctrl.log" 2>&1 &
PIDS+=("$!")
sleep 5

python3 "${PROJECT_ROOT}/Scripts/sunray/goal4_pointcloud_to_world_node.py" \
  _input_point_topic:="${RAW_LIDAR_TOPIC}" \
  _output_point_topic:="${WORLD_CLOUD_TOPIC}" \
  _odom_topic:="${POINTCLOUD_ODOM_TOPIC}" \
  _frame_id:=world \
  _mount_mode:="${POINTCLOUD_MOUNT_MODE}" \
  _rotation_mode:="${POINTCLOUD_ROTATION_MODE}" \
  _mount_xyz:="${POINTCLOUD_MOUNT_XYZ}" \
  _mount_rpy:="${POINTCLOUD_MOUNT_RPY}" \
  _min_sensor_range_m:="${POINTCLOUD_MIN_SENSOR_RANGE_M}" \
  _max_sensor_range_m:="${POINTCLOUD_MAX_SENSOR_RANGE_M}" \
  _self_filter_radius_m:="${POINTCLOUD_SELF_FILTER_RADIUS_M}" \
  _min_world_z_m:="${POINTCLOUD_MIN_WORLD_Z_M}" \
  _max_world_z_m:="${POINTCLOUD_MAX_WORLD_Z_M}" \
  _max_odom_cloud_dt_s:="${POINTCLOUD_MAX_ODOM_CLOUD_DT_S}" \
  _odom_sync_mode:="${POINTCLOUD_ODOM_SYNC_MODE}" \
  _output_stamp_mode:="${POINTCLOUD_OUTPUT_STAMP_MODE}" \
  _mixed_time_threshold_s:="${POINTCLOUD_MIXED_TIME_THRESHOLD_S}" \
  _max_abs_odom_xy_m:="${POINTCLOUD_MAX_ABS_ODOM_XY_M}" \
  _min_odom_z_m:="${POINTCLOUD_MIN_ODOM_Z_M}" \
  _max_odom_z_m:="${POINTCLOUD_MAX_ODOM_Z_M}" \
  _max_abs_roll_pitch_deg:="${POINTCLOUD_MAX_ABS_ROLL_PITCH_DEG}" \
  _min_publish_points:="${POINTCLOUD_MIN_PUBLISH_POINTS}" \
  _odom_buffer_size:="${POINTCLOUD_ODOM_BUFFER_SIZE}" \
  _diagnostics_path:="${RESULT_DIR}/pointcloud_to_world_stats.json" \
  _history_path:="${RESULT_DIR}/pointcloud_to_world_history.jsonl" \
  > "${RESULT_DIR}/pointcloud_to_world.log" 2>&1 &
PIDS+=("$!")

if [[ "${PLANNER_VARIANT}" == "diff_planner" && "${DIFF_GOAL4_COMMON_WORLD_FRAME}" == "true" ]]; then
  # This bridge adds the Factory L2 spawn offset, so its numeric pose is in
  # the same world frame as QGC goals and the planner cloud.
  python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
    _message_type:=odom \
    _direction:=local_to_world \
    _input_topic:=/uav1/mavros/local_position/odom \
    _output_topic:="${DIFF_GOAL4_PLANNER_ODOM_TOPIC}" \
    _offset_x:="${SUNRAY_UAV_INIT_X}" \
    _offset_y:="${SUNRAY_UAV_INIT_Y}" \
    _offset_z:=0.0 \
    _output_frame_id:=world \
    _diagnostics_path:="${RESULT_DIR}/diff_goal4_planner_odom_world_bridge.json" \
    > "${RESULT_DIR}/diff_goal4_planner_odom_world_bridge.log" 2>&1 &
  PIDS+=("$!")
  if ! python3 "${PROJECT_ROOT}/Scripts/sunray/wait_for_topic_sample.py" \
    --topic "${DIFF_GOAL4_PLANNER_ODOM_TOPIC}" \
    --timeout-s "${ODOM_BRIDGE_READY_TIMEOUT_S}" \
    --output "${RESULT_DIR}/diff_goal4_planner_odom_world_first.txt"; then
    echo "Diff Goal4 planner world odometry bridge did not produce a sample" >&2
    exit 64
  fi
fi

if [[ "${PLANNER_VARIANT}" == "fuel" && "${FUEL_SENSOR_POSE_SOURCE}" == "fastlio" ]]; then
  start_fastlio_stack
fi

if [[ "${PLANNER_VARIANT}" == "fuel" && "${FUEL_SENSOR_POSE_SOURCE}" == "pointcloud_odom" ]]; then
