if [[ "${PLANNER_VARIANT}" == "fuel" ]]; then
  if [[ "${FUEL_FRAME_BRIDGE_ENABLED}" == "true" ]]; then
    python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
      _message_type:=odom \
      _direction:=world_to_local \
      _input_topic:=/uav1/mavros/local_position/odom \
      _output_topic:="${FUEL_LOCAL_ODOM_TOPIC}" \
      _offset_x:="${FUEL_STATE_INPUT_OFFSET_X}" \
      _offset_y:="${FUEL_STATE_INPUT_OFFSET_Y}" \
      _offset_z:="${FUEL_STATE_INPUT_OFFSET_Z}" \
      _output_frame_id:=world \
      _output_child_frame_id:=world \
      _rotate_odom_twist_body_to_world:=true \
      _diagnostics_path:="${RESULT_DIR}/fuel_local_odom_bridge.json" \
      > "${RESULT_DIR}/fuel_local_odom_bridge.log" 2>&1 &
    PIDS+=("$!")

    python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
      _message_type:=pose \
      _direction:=world_to_local \
      _input_topic:=/uav1/mavros/local_position/pose \
      _output_topic:="${FUEL_LOCAL_POSE_TOPIC}" \
      _offset_x:="${FUEL_STATE_INPUT_OFFSET_X}" \
      _offset_y:="${FUEL_STATE_INPUT_OFFSET_Y}" \
      _offset_z:="${FUEL_STATE_INPUT_OFFSET_Z}" \
      _output_frame_id:=world \
      _diagnostics_path:="${RESULT_DIR}/fuel_local_pose_bridge.json" \
      > "${RESULT_DIR}/fuel_local_pose_bridge.log" 2>&1 &
    PIDS+=("$!")

    python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
      _message_type:=cloud \
      _direction:=world_to_local \
      _input_topic:="${WORLD_CLOUD_TOPIC}" \
      _output_topic:="${FUEL_LOCAL_CLOUD_TOPIC}" \
      _offset_x:="${FUEL_FRAME_OFFSET_X}" \
      _offset_y:="${FUEL_FRAME_OFFSET_Y}" \
      _offset_z:="${FUEL_FRAME_OFFSET_Z}" \
      _output_frame_id:=world \
      _diagnostics_path:="${RESULT_DIR}/fuel_local_cloud_bridge.json" \
      > "${RESULT_DIR}/fuel_local_cloud_bridge.log" 2>&1 &
    PIDS+=("$!")

    python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
      _message_type:=cloud \
      _direction:=local_to_world \
      _input_topic:=/sdf_map/occupancy_all \
      _output_topic:="${FUEL_OCCUPANCY_GLOBAL_TOPIC}" \
      _offset_x:="${FUEL_FRAME_OFFSET_X}" \
      _offset_y:="${FUEL_FRAME_OFFSET_Y}" \
      _offset_z:="${FUEL_FRAME_OFFSET_Z}" \
      _output_frame_id:=world \
      _diagnostics_path:="${RESULT_DIR}/fuel_occupancy_global_bridge.json" \
      > "${RESULT_DIR}/fuel_occupancy_global_bridge.log" 2>&1 &
    PIDS+=("$!")

    if [[ "${FUEL_VISUALIZATION_BRIDGE_ENABLED}" == "true" ]]; then
      while IFS='|' read -r marker_input marker_output marker_name; do
        python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
          _message_type:=marker \
          _direction:=local_to_world \
          _input_topic:="${marker_input}" \
          _output_topic:="${marker_output}" \
          _offset_x:="${FUEL_FRAME_OFFSET_X}" \
          _offset_y:="${FUEL_FRAME_OFFSET_Y}" \
          _offset_z:="${FUEL_FRAME_OFFSET_Z}" \
          _output_frame_id:=world \
          _diagnostics_path:="${RESULT_DIR}/fuel_visualization_${marker_name}_bridge.json" \
          > "${RESULT_DIR}/fuel_visualization_${marker_name}_bridge.log" 2>&1 &
        PIDS+=("$!")
      done <<EOF
/planning_vis/trajectory|/mosim/fuel/planning_vis/trajectory_world|trajectory
/planning_vis/frontier|/mosim/fuel/planning_vis/frontier_world|frontier
/planning_vis/viewpoints|/mosim/fuel/planning_vis/viewpoints_world|viewpoints
EOF
    fi
    sleep 1
  fi

  if [[ "${FUEL_COVERAGE_VISUALIZATION_ENABLED}" == "true" ]]; then
    python3 "${PROJECT_ROOT}/Scripts/sunray/fuel_coverage_visualization.py" \
      _odom_topic:=/uav1/mavros/local_position/odom \
      _output_topic:=/mosim/fuel/coverage_overlay \
      _frame_id:=world \
      _boundary_min_x:="${FUEL_COVERAGE_VISUALIZATION_MIN_X}" \
      _boundary_max_x:="${FUEL_COVERAGE_VISUALIZATION_MAX_X}" \
      _boundary_min_y:="${FUEL_COVERAGE_VISUALIZATION_MIN_Y}" \
      _boundary_max_y:="${FUEL_COVERAGE_VISUALIZATION_MAX_Y}" \
      _resolution_m:="${FUEL_COVERAGE_VISUALIZATION_RESOLUTION_M}" \
      _sensor_radius_m:="${FUEL_COVERAGE_VISUALIZATION_SENSOR_RADIUS_M}" \
      _plane_z_m:=0.08 \
      _publish_rate_hz:=1.0 \
      _diagnostics_path:="${RESULT_DIR}/fuel_coverage_visualization.json" \
      > "${RESULT_DIR}/fuel_coverage_visualization.log" 2>&1 &
    PIDS+=("$!")
  fi

  if [[ "${FUEL_SENSOR_POSE_SOURCE}" == "fastlio" ]]; then
    fuel_fastlio_alignment_reference_topic="${FUEL_LOCAL_ODOM_TOPIC}"
    if [[ "${FUEL_FRAME_BRIDGE_ENABLED}" != "true" ]]; then
      fuel_fastlio_alignment_reference_topic=/uav1/mavros/local_position/odom
    fi
    python3 "${PROJECT_ROOT}/Scripts/sunray/fastlio_odom_alignment_adapter.py" \
      --node-name mosim_fuel_fastlio_local_alignment_adapter \
      --fastlio-topic "${FUEL_FASTLIO_ODOM_TOPIC}" \
      --local-topic "${fuel_fastlio_alignment_reference_topic}" \
      --output-topic "${FUEL_FASTLIO_ALIGNED_LOCAL_ODOM_TOPIC}" \
      --path-topic /mosim/fuel/fastlio_odom_aligned_local_path \
      --delay-topic /mosim/fuel/fastlio_odom_aligned_local_delay \
      --cloud-input-topic "${FUEL_FASTLIO_CLOUD_TOPIC}" \
      --cloud-output-topic "${FUEL_FASTLIO_ALIGNED_LOCAL_CLOUD_TOPIC}" \
      --cloud-diagnostics-path "${RESULT_DIR}/fuel_fastlio_cloud_odom_alignment.json" \
      --dynamic-diagnostics-csv "${RESULT_DIR}/fuel_fastlio_dynamic_alignment.csv" \
      --dynamic-diagnostics-json "${RESULT_DIR}/fuel_fastlio_dynamic_alignment.json" \
      --truth-topic /uav1/sunray/gazebo_pose \
      --alignment-reference local \
      --z-source "${FUEL_FASTLIO_ALIGNMENT_Z_SOURCE}" \
      --output-frame world \
      --child-frame fuel_fastlio_base_link \
      --stamp-source measurement \
      --input-pose-frame livox \
      --mount-xyz "${FASTLIO_MOUNT_XYZ}" \
      --mount-rpy "${FASTLIO_MOUNT_RPY}" \
      > "${RESULT_DIR}/fuel_fastlio_cloud_odom_alignment.log" 2>&1 &
    PIDS+=("$!")
    sleep 2
  fi

  python3 "${PROJECT_ROOT}/Scripts/sunray/fuel_bspline_bridge.py" \
    _input_topic:="${PLANNER_TRAJ_TOPIC}" \
    _output_topic:="${FUEL_TRAJ_UTILS_BSPLINE_TOPIC}" \
    _diagnostics_path:="${RESULT_DIR}/fuel_bspline_bridge.json" \
    > "${RESULT_DIR}/fuel_bspline_bridge.log" 2>&1 &
  PIDS+=("$!")
  sleep 1

  python3 "${PROJECT_ROOT}/Scripts/sunray/fuel_position_cmd_compat_bridge.py" \
    _input_topic:="${FUEL_NATIVE_POSITION_CMD_TOPIC}" \
    _output_topic:="${FUEL_RAW_POSITION_CMD_TOPIC}" \
    _gate_bspline_topic:="${PLANNER_TRAJ_TOPIC}" \
    _forward_before_first_bspline:="${FUEL_FORWARD_BEFORE_FIRST_BSPLINE}" \
    _output_offset_x:="${FUEL_OUTPUT_OFFSET_X}" \
    _output_offset_y:="${FUEL_OUTPUT_OFFSET_Y}" \
    _output_offset_z:="${FUEL_OUTPUT_OFFSET_Z}" \
    _diagnostics_path:="${RESULT_DIR}/fuel_position_cmd_compat_bridge.json" \
    > "${RESULT_DIR}/fuel_position_cmd_compat_bridge.log" 2>&1 &
  PIDS+=("$!")
  sleep 1

  python3 "${PROJECT_ROOT}/Scripts/sunray/fuel_trigger_path_adapter.py" \
    _input_topic:=/traj_start_trigger \
    _output_topic:="${FUEL_TRIGGER_PATH_TOPIC}" \
    _frame_id:=world \
    _min_z:=0.0 \
    _apply_input_offset:="${FUEL_TRIGGER_APPLY_INPUT_OFFSET}" \
    _offset_x:="${FUEL_FRAME_OFFSET_X}" \
    _offset_y:="${FUEL_FRAME_OFFSET_Y}" \
    _offset_z:="${FUEL_FRAME_OFFSET_Z}" \
    _repeat_count:="${FUEL_TRIGGER_REPEAT_COUNT}" \
    _repeat_interval_s:="${FUEL_TRIGGER_REPEAT_INTERVAL_S}" \
    _diagnostics_path:="${RESULT_DIR}/fuel_trigger_path_adapter.json" \
    > "${RESULT_DIR}/fuel_trigger_path_adapter.log" 2>&1 &
  PIDS+=("$!")
  sleep 1

  start_fuel_native_traj_server
  sleep 1

  if [[ "${FUEL_COVERAGE_SUPERVISOR_ENABLED}" == "true" ]]; then
    python3 "${PROJECT_ROOT}/Scripts/sunray/factory_l2_same_flight_coverage_supervisor.py" \
      _result_path:="${RESULT_DIR}/factory_l2_same_flight_coverage_supervisor.json" \
      _trigger_topic:=/traj_start_trigger \
      _odom_topic:=/uav1/mavros/local_position/odom \
      _bspline_topic:="${PLANNER_TRAJ_TOPIC}" \
      _position_cmd_topic:="${FUEL_RAW_POSITION_CMD_TOPIC}" \
      _target_z:="${TARGET_Z}" \
      _boundary_min_x:="${FACTORY_INDOOR_BOUNDARY_MIN_X:-${FUEL_BOX_MIN_X}}" \
      _boundary_max_x:="${FACTORY_INDOOR_BOUNDARY_MAX_X:-${FUEL_BOX_MAX_X}}" \
      _boundary_min_y:="${FACTORY_INDOOR_BOUNDARY_MIN_Y:-${FUEL_BOX_MIN_Y}}" \
      _boundary_max_y:="${FACTORY_INDOOR_BOUNDARY_MAX_Y:-${FUEL_BOX_MAX_Y}}" \
      _coverage_resolution_m:="${FUEL_COVERAGE_SUPERVISOR_GRID_RESOLUTION_M}" \
      _sensor_radius_m:="${FUEL_COVERAGE_SUPERVISOR_SENSOR_RADIUS_M}" \
      _min_required_ratio:="${FUEL_COVERAGE_SUPERVISOR_MIN_RATIO}" \
      _initial_delay_s:="${FUEL_COVERAGE_SUPERVISOR_INITIAL_DELAY_S}" \
      _trigger_interval_s:="${FUEL_COVERAGE_SUPERVISOR_TRIGGER_INTERVAL_S}" \
      _stale_bspline_s:="${FUEL_COVERAGE_SUPERVISOR_STALE_BSPLINE_S}" \
      _min_trigger_move_m:="${FUEL_COVERAGE_SUPERVISOR_MIN_TRIGGER_MOVE_M}" \
      _time_basis:="${FUEL_COVERAGE_SUPERVISOR_TIME_BASIS}" \
      _trigger_require_target_z:="${FUEL_COVERAGE_SUPERVISOR_REQUIRE_TARGET_Z}" \
      _trigger_z_tolerance_m:="${FUEL_COVERAGE_SUPERVISOR_TRIGGER_Z_TOLERANCE_M}" \
      _max_runtime_s:="${FUEL_COVERAGE_SUPERVISOR_MAX_RUNTIME_S}" \
      _no_growth_timeout_s:="${FUEL_COVERAGE_SUPERVISOR_NO_GROWTH_TIMEOUT_S}" \
      _min_growth_cells:="${FUEL_COVERAGE_SUPERVISOR_MIN_GROWTH_CELLS}" \
      > "${RESULT_DIR}/factory_l2_same_flight_coverage_supervisor.log" 2>&1 &
    PIDS+=("$!")
    sleep 1
  fi
fi

