fi

roslaunch "${PLANNER_LAUNCH}" \
  target_x:="${TARGET_X}" target_y:="${TARGET_Y}" target_z:="${TARGET_Z}" \
  max_vel:="${EGO_MAX_VEL}" max_acc:="${EGO_MAX_ACC}" max_jer:="${EGO_MAX_JERK}" planning_horizon:="${EGO_PLANNING_HORIZON}" \
  grid_resolution:="${EGO_GRID_RESOLUTION}" obstacles_inflation:="${EGO_OBSTACLES_INFLATION}" \
  optimization_dist0:="${EGO_OPTIMIZATION_DIST0}" obstacle_clearance:="${EGO_OBSTACLE_CLEARANCE}" obstacle_clearance_soft:="${EGO_OBSTACLE_CLEARANCE_SOFT}" \
  virtual_ceil_height:="${EGO_VIRTUAL_CEIL_HEIGHT}" visualization_truncate_height:="${EGO_VISUALIZATION_TRUNCATE_HEIGHT}" \
  odom_topic:="${PLANNER_EFFECTIVE_ODOM_TOPIC}" global_pointcloud_topic:="${WORLD_CLOUD_TOPIC}" \
  position_cmd_topic:="${PLANNER_POSITION_CMD_TOPIC}" \
  "${PLANNER_EXTRA_LAUNCH_ARGS[@]}" \
  > "${RESULT_DIR}/ego_single_px4ctrl_goal4.log" 2>&1 &
PLANNER_PID=$!
PIDS+=("${PLANNER_PID}")
sleep 3

PLANNER_LAUNCH_STATUS="started"
PLANNER_LAUNCH_BLOCKER=""
if ! kill -0 "${PLANNER_PID}" >/dev/null 2>&1; then
  PLANNER_LAUNCH_STATUS="failed"
  PLANNER_LAUNCH_BLOCKER="planner_process_exited_early"
fi
if grep -qE "RLException|requires the '.+' arg to be set|unused args|ERROR:" "${RESULT_DIR}/ego_single_px4ctrl_goal4.log" 2>/dev/null; then
  PLANNER_LAUNCH_STATUS="failed"
  PLANNER_LAUNCH_BLOCKER="planner_launch_log_error"
fi
cat > "${RESULT_DIR}/planner_launch_gate.json" <<EOF
{
  "schema": "mosim.sunray_ros1.planner_launch_gate.v1",
  "status": "${PLANNER_LAUNCH_STATUS}",
  "planner_variant": "${PLANNER_VARIANT}",
  "planner_launch": "${PLANNER_LAUNCH}",
  "blocker": "${PLANNER_LAUNCH_BLOCKER}",
  "log": "ego_single_px4ctrl_goal4.log"
}
EOF
if [[ "${PLANNER_LAUNCH_STATUS}" != "started" ]]; then
  echo "Planner launch failed; see ${RESULT_DIR}/planner_launch_gate.json and ego_single_px4ctrl_goal4.log" >&2
  exit 63
fi

if [[ "${PLANNER_VARIANT}" == "diff_planner" && "${DIFF_GOAL4_COMMON_WORLD_FRAME}" == "true" ]]; then
  # The inverse bridge restores PX4/MAVROS-local coordinates for px4ctrl.
  python3 "${PROJECT_ROOT}/Scripts/ros/ros1_coordinate_offset_bridge.py" \
    _message_type:=position_cmd \
    _direction:=world_to_local \
    _input_topic:="${DIFF_GOAL4_PLANNER_POSITION_CMD_WORLD_TOPIC}" \
    _output_topic:="${DIFF_RAW_POSITION_CMD_TOPIC}" \
    _offset_x:="${SUNRAY_UAV_INIT_X}" \
    _offset_y:="${SUNRAY_UAV_INIT_Y}" \
    _offset_z:=0.0 \
    _output_frame_id:=map \
    _diagnostics_path:="${RESULT_DIR}/diff_goal4_planner_position_cmd_local_bridge.json" \
    > "${RESULT_DIR}/diff_goal4_planner_position_cmd_local_bridge.log" 2>&1 &
  DIFF_GOAL4_COMMAND_BRIDGE_PID=$!
  PIDS+=("${DIFF_GOAL4_COMMAND_BRIDGE_PID}")
  sleep 1
  if ! kill -0 "${DIFF_GOAL4_COMMAND_BRIDGE_PID}" >/dev/null 2>&1; then
    echo "Diff Goal4 planner world-to-local command bridge exited during startup" >&2
    exit 64
  fi
fi

if [[ "${PLANNER_VARIANT}" == "highstar" ]]; then
