if [[ "${ENABLE_OCCUPANCY_REVIEW_ACCUMULATION}" == "true" && "${OCCUPANCY_MSG_TYPE}" == "pointcloud2" && -n "${OCCUPANCY_REVIEW_SOURCE_TOPIC}" && ( "${PLANNER_VARIANT}" == "diff_planner" || "${PLANNER_VARIANT}" == "fuel" || "${PLANNER_VARIANT}" == "racer" || "${PLANNER_VARIANT}" == "highstar" ) ]]; then
