{
  "schema": "mosim.ue.live_ros1_mirror.config.v1",
  "source": "Gazebo/PX4/MAVROS/px4ctrl ROS1 live graph",
  "display_only": true,
  "odom_topic": "${UE_LIVE_MIRROR_ODOM_TOPIC}",
