    --vehicle-id uav1 \
    --scene-id factory \
    --map-id local_factoryenvironmentcollect \
    --controller-profile "${PX4CTRL_CORE_PROFILE}" \
    --planner-profile "${PLANNER_VARIANT}_interactive" \
    > "${RESULT_DIR}/ue_live_mirror.log" 2>&1 &
  PIDS+=("$!")
  sleep 1
fi

if [[ "${OPEN_RVIZ}" == "true" ]]; then
