    PIDS+=("$!")
    rviz -d "${DIFF_GRID3D_RVIZ_CONFIG}" > "${RESULT_DIR}/rviz_diff_grid3d_review.log" 2>&1 &
    PIDS+=("$!")
  elif [[ "${PLANNER_VARIANT}" == "fuel" && "${FUEL_OPEN_SPLIT_RVIZ}" == "true" ]]; then
