fi
if [[ "${EGO_SKIP_LAND_AFTER_EXPLORATION}" == "true" ]]; then
  MISSION_ADAPTER_ARGS+=(--skip-land-after-exploration)
fi
if [[ "${PLANNER_VARIANT}" == "racer" ]]; then
  MISSION_ADAPTER_ARGS+=(
    --allow-empty-final-occupancy
    --allow-discontinuous-raw-planner-position-cmd
    --frontier-topic "${PLANNER_FRONTIER_TOPIC}"
    --trajectory-vis-topic "${PLANNER_TRAJECTORY_VIS_TOPIC}"
    --min-frontier-count "${RACER_SINGLE_MIN_FRONTIER_COUNT}"
    --min-trajectory-vis-count "${RACER_SINGLE_MIN_TRAJECTORY_VIS_COUNT}"
  )
fi
if [[ "${PLANNER_VARIANT}" == "falcon" ]]; then
  MISSION_ADAPTER_ARGS+=(
    --allow-empty-final-occupancy
    --allow-discontinuous-raw-planner-position-cmd
    --frontier-topic "${PLANNER_FRONTIER_TOPIC}"
    --frontier-msg-type pointcloud2
    --trajectory-vis-topic "${PLANNER_TRAJECTORY_VIS_TOPIC}"
    --min-frontier-count 1
    --min-trajectory-vis-count 1
  )
fi
if [[ "${PLANNER_VARIANT}" == "uav_frontier" ]]; then
  MISSION_ADAPTER_ARGS+=(
    --allow-empty-final-occupancy
    --allow-discontinuous-raw-planner-position-cmd
    --frontier-topic "${PLANNER_FRONTIER_TOPIC}"
    --min-frontier-count 1
    --min-planner-traj-count 0
  )
fi
if [[ "${PLANNER_VARIANT}" == "highstar" ]]; then
  MISSION_ADAPTER_ARGS+=(
    --allow-empty-final-occupancy
    --allow-discontinuous-raw-planner-position-cmd
    --frontier-topic "${PLANNER_FRONTIER_TOPIC}"
    --frontier-msg-type "${PLANNER_FRONTIER_MSG_TYPE}"
    --trajectory-vis-topic "${PLANNER_TRAJECTORY_VIS_TOPIC}"
    --trajectory-vis-msg-type "${PLANNER_TRAJECTORY_VIS_MSG_TYPE}"
    --min-frontier-count 1
    --min-trajectory-vis-count 1
    --min-planner-traj-count 0
  )
fi

MISSION_CMD=(
  python3 "${PROJECT_ROOT}/Scripts/sunray/px4ctrl_ego_single_mission_node.py" \
  --result-dir "${RESULT_DIR}" \
  --target-x "${TARGET_X}" --target-y "${TARGET_Y}" --target-z "${TARGET_Z}" \
  --path-odom-topic "${DIFF_GOAL4_PATH_ODOM_TOPIC}" \
  --raw-lidar-topic "${RAW_LIDAR_TOPIC}" \
  --world-cloud-topic "${WORLD_CLOUD_TOPIC}" \
  --occupancy-topic "${OCCUPANCY_TOPIC}" \
  --occupancy-msg-type "${OCCUPANCY_MSG_TYPE}" \
  --bspline-topic "${PLANNER_TRAJ_TOPIC}" \
  --bspline-msg-package "${PLANNER_BSPLINE_MSG_PACKAGE}" \
  --polytraj-topic "${PLANNER_POLYTRAJ_TOPIC}" \
  --planner-position-cmd-topic "${PLANNER_POSITION_CMD_MONITOR_TOPIC}" \
  --goalset-topic "${PLANNER_GOALSET_TOPIC}" \
  --goal-pose-topic "${PLANNER_GOAL_POSE_TOPIC}" \
  --mission-mode "${PLANNER_MISSION_MODE}" \
  --takeoff-height "${GOAL4_TAKEOFF_HEIGHT}" \
  --takeoff-z-tol "${GOAL4_TAKEOFF_Z_TOL}" \
  --cmd-adapter-enable-topic "${DIFF_CMD_ADAPTER_ENABLE_TOPIC}" \
  --min-planner-command-count "${PLANNER_POSITION_CMD_MIN_COUNT}" \
  --max-position-cmd-jump-m "${DIFF_CMD_SAFETY_MAX_POSITION_JUMP_M}" \
  --max-position-cmd-speed-mps "${DIFF_CMD_SAFETY_MAX_POSITION_JUMP_SPEED_MPS}" \
  --max-raw-planner-position-cmd-jump-m "${PLANNER_RAW_CMD_MAX_POSITION_JUMP_M}" \
  --max-raw-planner-position-cmd-speed-mps "${PLANNER_RAW_CMD_MAX_POSITION_JUMP_SPEED_MPS}" \
  --ego-takeover-timeout-s "${GOAL4_EGO_TAKEOVER_TIMEOUT_S}" \
  --takeoff-timeout-s "${GOAL4_TAKEOFF_TIMEOUT_S}" \
  --land-timeout-s "${GOAL4_LAND_TIMEOUT_S}" \
  --takeoff-retry-interval-s "${TAKEOFF_RETRY_INTERVAL_S}" \
  --takeoff-retry-repeats "${TAKEOFF_RETRY_REPEATS}" \
  --takeoff-retry-max "${TAKEOFF_RETRY_MAX}" \
  --takeoff-rise-detect-m "${TAKEOFF_RISE_DETECT_M}" \
  --post-adapter-disable-wait-s "${DIFF_POST_ADAPTER_DISABLE_WAIT_S}" \
  --record-hz "${GOAL4_RECORD_HZ}" \
  --record-cmd-hz "${GOAL4_RECORD_CMD_HZ}" \
  --max-path-points "${GOAL4_MAX_PATH_POINTS}" \
  --path-publish-hz "${GOAL4_PATH_PUBLISH_HZ}" \
  --body-axis-length-m "${GOAL4_BODY_AXIS_LENGTH_M}" \
  --body-axis-shaft-m "${GOAL4_BODY_AXIS_SHAFT_M}" \
  --body-axis-head-diameter-m "${GOAL4_BODY_AXIS_HEAD_DIAMETER_M}" \
  --body-axis-head-length-m "${GOAL4_BODY_AXIS_HEAD_LENGTH_M}" \
  --body-axis-lifetime-s "${GOAL4_BODY_AXIS_LIFETIME_S}" \
  --cmd-path-segment-jump-m "${GOAL4_CMD_PATH_SEGMENT_JUMP_M}" \
  --exploration-max-trajectory-stale-s "${EXPLORATION_MAX_TRAJECTORY_STALE_S:-10}" \
  "${MISSION_ADAPTER_ARGS[@]}"
)
set +e
if [[ "${TOTAL_TIMEOUT_S}" == "0" || "${TOTAL_TIMEOUT_S}" == "0.0" || "${TOTAL_TIMEOUT_S}" == "-1" ]]; then
  "${MISSION_CMD[@]}" > "${RESULT_DIR}/px4ctrl_ego_single_mission.log" 2>&1
else
  timeout "${TOTAL_TIMEOUT_S}s" "${MISSION_CMD[@]}" > "${RESULT_DIR}/px4ctrl_ego_single_mission.log" 2>&1
fi
MISSION_EXIT_CODE=$?
set -e

if [[ "${PX4CTRL_ENABLE_FASTLIO_EKF_FUSION}" == "true" ]]; then
  CONTROL_INPUT_PATH="FAST-LIO /Odometry -> aligned odom -> timestamp-consistent MAVROS odometry/out -> MAVLink ODOMETRY -> PX4 EKF -> /uav1/mavros/local_position/odom -> px4ctrl"
elif [[ "${PX4CTRL_START_EXTERNAL_FUSION}" == "true" ]]; then
  CONTROL_INPUT_PATH="Gazebo truth odometry -> external_fusion -> /uav1/mavros/vision_pose/pose -> PX4 EKF -> /uav1/mavros/local_position/odom -> px4ctrl"
else
  CONTROL_INPUT_PATH="PX4 simulator estimator -> /uav1/mavros/local_position/odom -> px4ctrl"
fi

