      "max_accum_speed_z_mps": ${POINTCLOUD_REVIEW_MAX_ACCUM_SPEED_Z_MPS}
    }
  },
  "occupancy_review": {
    "topic": "${OCCUPANCY_REVIEW_TOPIC}",
    "source": "${OCCUPANCY_REVIEW_SOURCE_TOPIC}",
    "voxel_size_m": ${OCCUPANCY_REVIEW_VOXEL_SIZE_M},
    "max_points_per_cloud": ${OCCUPANCY_REVIEW_MAX_POINTS_PER_CLOUD},
    "max_accumulated_points": ${OCCUPANCY_REVIEW_MAX_ACCUMULATED_POINTS},
    "publish_rate_hz": ${OCCUPANCY_REVIEW_PUBLISH_RATE_HZ},
    "max_runtime_s": ${OCCUPANCY_REVIEW_MAX_RUNTIME_S},
    "scope": "review_only_not_planner_input",
    "quality_gate": {
      "enabled": $(if [[ -n "${OCCUPANCY_REVIEW_QUALITY_ODOM_TOPIC}" ]]; then echo true; else echo false; fi),
      "odom_topic": "${OCCUPANCY_REVIEW_QUALITY_ODOM_TOPIC}",
      "max_odom_age_s": ${OCCUPANCY_REVIEW_MAX_ODOM_AGE_S},
      "min_odom_z_for_accumulation": ${OCCUPANCY_REVIEW_MIN_ODOM_Z_FOR_ACCUMULATION},
      "max_accum_roll_pitch_deg": ${OCCUPANCY_REVIEW_MAX_ACCUM_ROLL_PITCH_DEG},
      "max_accum_yaw_rate_deg_s": ${OCCUPANCY_REVIEW_MAX_ACCUM_YAW_RATE_DEG_S},
      "max_accum_speed_xy_mps": ${OCCUPANCY_REVIEW_MAX_ACCUM_SPEED_XY_MPS},
      "max_accum_speed_z_mps": ${OCCUPANCY_REVIEW_MAX_ACCUM_SPEED_Z_MPS}
    }
  },
  "continuous_occupancy_review": {
    "enabled": ${ENABLE_CONTINUOUS_OCCUPANCY_REVIEW},
    "topic": "${CONTINUOUS_OCCUPANCY_REVIEW_TOPIC}",
    "source": "${CONTINUOUS_OCCUPANCY_REVIEW_SOURCE_TOPIC}",
    "voxel_size_m": ${CONTINUOUS_OCCUPANCY_REVIEW_VOXEL_SIZE_M},
    "min_z_m": ${CONTINUOUS_OCCUPANCY_REVIEW_MIN_Z},
    "max_z_m": ${CONTINUOUS_OCCUPANCY_REVIEW_MAX_Z},
    "closing_iterations": ${CONTINUOUS_OCCUPANCY_REVIEW_CLOSING_ITERATIONS},
    "connectivity": $(if [[ "${CONTINUOUS_OCCUPANCY_REVIEW_CONNECTIVITY}" == "3" ]]; then echo 26; elif [[ "${CONTINUOUS_OCCUPANCY_REVIEW_CONNECTIVITY}" == "2" ]]; then echo 18; else echo 6; fi),
    "min_component_voxels": ${CONTINUOUS_OCCUPANCY_REVIEW_MIN_COMPONENT_VOXELS},
    "scope": "review_only_not_planner_input"
  },
  "mission_exit_code": ${MISSION_EXIT_CODE},
  "claim_boundary": "Goal4 single-UAV planner closed-loop through px4ctrl/MAVROS/PX4/Gazebo; PX4CTRL_CORE_PROFILE selects original, MWORKS generated, or G9/G10 ATTITUDE_THRUST generated-family controller backend. FAST-LIO may enter only through the PX4 EKF MAVLink ODOMETRY path, while px4ctrl remains subscribed to /uav1/mavros/local_position/odom."
}
EOF

FINAL_EXIT_CODE="${MISSION_EXIT_CODE}"
if [[ "${PX4CTRL_FASTLIO_ODOMETRY_FUSION_ENABLED}" == "true" ]]; then
  set +e
  python3 - \
    "${RESULT_DIR}/fastlio_mavros_odometry_adapter.json" \
    "${RESULT_DIR}/mavros_odometry_plugin_audit.txt" \
    "${RESULT_DIR}/FASTLIO_MAVROS_ODOMETRY_GATE.json" <<'PY'
import json
import sys
from pathlib import Path

diagnostics_path = Path(sys.argv[1])
plugin_audit_path = Path(sys.argv[2])
output_path = Path(sys.argv[3])
blockers = []
diagnostics = {}
if diagnostics_path.is_file():
    diagnostics = json.loads(diagnostics_path.read_text(encoding="utf-8"))
else:
    blockers.append("missing_adapter_diagnostics")

counts = diagnostics.get("counts", {})
received = int(counts.get("received", 0) or 0)
published = int(counts.get("published", 0) or 0)
measurement_rate_hz = diagnostics.get("published_measurement_rate_hz")
stamp_delta_s = diagnostics.get("last_input_output_stamp_delta_s")
if published < 20:
    blockers.append("insufficient_odometry_samples")
if measurement_rate_hz is None or float(measurement_rate_hz) < 10.0:
    blockers.append("odometry_measurement_rate_below_10hz")
if stamp_delta_s is None or abs(float(stamp_delta_s)) > 1e-9:
    blockers.append("measurement_stamp_not_preserved")
stale_count = int(counts.get("dropped_stale", 0) or 0)
stale_limit = max(5, int(received * 0.01 + 0.999999))
if stale_count > stale_limit:
    blockers.append("dropped_stale_exceeds_limit")
for key in (
    "dropped_nonfinite",
    "dropped_zero_stamp",
    "dropped_future",
    "dropped_duplicate",
    "dropped_out_of_order",
    "dropped_frame_mismatch",
):
    if int(counts.get(key, 0) or 0) != 0:
        blockers.append(key)

plugin_subscribed = False
if plugin_audit_path.is_file():
    plugin_text = plugin_audit_path.read_text(encoding="utf-8", errors="replace")
    plugin_subscribed = "* /uav1/mavros " in plugin_text or "* /uav1/mavros\n" in plugin_text
if not plugin_subscribed:
    blockers.append("mavros_odom_plugin_not_subscribed")

result = {
    "schema": "mosim.fastlio_mavros_odometry_gate.v1",
    "status": "passed" if not blockers else "blocked",
    "blockers": blockers,
    "received": received,
    "published": published,
    "published_measurement_rate_hz": measurement_rate_hz,
    "last_input_output_stamp_delta_s": stamp_delta_s,
    "stale_drop_limit": stale_limit,
    "stale_drop_fraction": (stale_count / received) if received else None,
    "drop_counts": {key: counts.get(key, 0) for key in counts if key.startswith("dropped_")},
    "mavros_odom_plugin_subscribed": plugin_subscribed,
    "diagnostics": str(diagnostics_path),
    "plugin_audit": str(plugin_audit_path),
}
output_path.write_text(json.dumps(result, indent=2), encoding="utf-8")
raise SystemExit(0 if not blockers else 17)
PY
  FASTLIO_MAVROS_ODOMETRY_GATE_EXIT_CODE=$?
  set -e
  if [[ "${FASTLIO_MAVROS_ODOMETRY_GATE_EXIT_CODE}" -ne 0 && "${FINAL_EXIT_CODE}" -eq 0 ]]; then
    FINAL_EXIT_CODE="${FASTLIO_MAVROS_ODOMETRY_GATE_EXIT_CODE}"
  fi
fi
if [[ "${PX4CTRL_START_EXTERNAL_FUSION}" == "true" && -s "${RESULT_DIR}/external_fusion.log" ]]; then
  fusion_total="$(grep -c '飞控融合状态:' "${RESULT_DIR}/external_fusion.log" || true)"
  fusion_success="$(grep -c '飞控融合状态: \[ 成功 \]' "${RESULT_DIR}/external_fusion.log" || true)"
  fusion_total="${fusion_total:-0}"
  fusion_success="${fusion_success:-0}"
  fusion_ratio="0"
  if (( fusion_total > 0 )); then
    fusion_ratio="$(awk -v ok="${fusion_success}" -v total="${fusion_total}" 'BEGIN { printf "%.6f", ok/total }')"
  fi
  {
    echo "fusion_status_samples=${fusion_total}"
    echo "fusion_success_samples=${fusion_success}"
    echo "fusion_success_ratio=${fusion_ratio}"
    echo "semantic=Sunray external-vs-local position consistency within 0.1 m; not a native PX4 EKF fusion flag"
    echo "gate=requires_consistent_samples_and_ratio_at_least_0.80"
  } > "${RESULT_DIR}/external_fusion_gate.txt"
  if (( fusion_total == 0 || fusion_success == 0 )) || awk -v ratio="${fusion_ratio}" 'BEGIN { exit !(ratio < 0.80) }'; then
    echo "External fusion did not remain successful; rejecting this run as control evidence." >&2
    FINAL_EXIT_CODE=16
  fi
fi
if [[ "${PLANNER_VARIANT}" == "diff_planner" && "${DIFF_ENABLE_Z_AUDIT}" == "true" ]]; then
  DIFF_Z_AUDIT_ARGS=(
    --result-dir "${RESULT_DIR}"
    --output-json "${RESULT_DIR}/DIFF_SINGLE_Z_AUDIT.json"
    --max-final-target-error-m "${DIFF_AUDIT_MAX_FINAL_TARGET_ERROR_M}"
    --max-replan-failures "${DIFF_AUDIT_MAX_REPLAN_FAILURES}"
    --max-position-cmd-jump-m "${DIFF_CMD_SAFETY_MAX_POSITION_JUMP_M}"
    --max-position-cmd-speed-mps "${DIFF_CMD_SAFETY_MAX_POSITION_JUMP_SPEED_MPS}"
  )
  if [[ -n "${DIFF_AUDIT_RAW_MIN_Z}" ]]; then
    DIFF_Z_AUDIT_ARGS+=(--raw-min-z "${DIFF_AUDIT_RAW_MIN_Z}")
  fi
  if [[ -n "${DIFF_AUDIT_RAW_MAX_Z}" ]]; then
    DIFF_Z_AUDIT_ARGS+=(--raw-max-z "${DIFF_AUDIT_RAW_MAX_Z}")
  fi
  if [[ -n "${DIFF_AUDIT_TARGET_Z_TOL}" ]]; then
    DIFF_Z_AUDIT_ARGS+=(--target-z-tol "${DIFF_AUDIT_TARGET_Z_TOL}")
  fi
  if [[ "${DIFF_AUDIT_ALLOW_REVIEW_HOLD}" == "true" ]]; then
    DIFF_Z_AUDIT_ARGS+=(--allow-review-hold)
  fi

  set +e
  python3 "${PROJECT_ROOT}/Scripts/sunray/analyze_diff_single_z_audit.py" \
    "${DIFF_Z_AUDIT_ARGS[@]}" \
    > "${RESULT_DIR}/diff_single_z_audit.log" 2>&1
  DIFF_Z_AUDIT_EXIT_CODE=$?
  set -e
  if [[ "${DIFF_Z_AUDIT_EXIT_CODE}" -ne 0 && "${FINAL_EXIT_CODE}" -eq 0 ]]; then
    FINAL_EXIT_CODE="${DIFF_Z_AUDIT_EXIT_CODE}"
  fi
fi

if [[ "${PLANNER_VARIANT}" == "diff_planner" && "${DIFF_ENABLE_WAYPOINT_AUDIT}" == "true" && "${DIFF_INTERACTIVE_CLICK_GOAL}" != "true" && "${DIFF_USE_MULTIPOINT}" == "true" ]]; then
  set +e
  python3 "${PROJECT_ROOT}/Scripts/sunray/analyze_diff_waypoint_audit.py" \
    --result-dir "${RESULT_DIR}" \
    --output-json "${RESULT_DIR}/DIFF_SINGLE_123_WAYPOINT_AUDIT.json" \
    --waypoint-yaml "${DIFF_MULTIPOINT_YAML}" \
    --waypoint-section "${DIFF_WAYPOINT_AUDIT_SECTION}" \
    --max-state-xyz-error-m "${DIFF_WAYPOINT_AUDIT_MAX_STATE_XYZ_ERROR_M}" \
    --max-state-z-error-m "${DIFF_WAYPOINT_AUDIT_MAX_STATE_Z_ERROR_M}" \
    --max-cmd-xyz-error-m "${DIFF_WAYPOINT_AUDIT_MAX_CMD_XYZ_ERROR_M}" \
    --max-cmd-z-error-m "${DIFF_WAYPOINT_AUDIT_MAX_CMD_Z_ERROR_M}" \
    > "${RESULT_DIR}/diff_single_waypoint_audit.log" 2>&1
  DIFF_WAYPOINT_AUDIT_EXIT_CODE=$?
  set -e
  if [[ "${DIFF_WAYPOINT_AUDIT_EXIT_CODE}" -ne 0 && "${FINAL_EXIT_CODE}" -eq 0 ]]; then
    FINAL_EXIT_CODE="${DIFF_WAYPOINT_AUDIT_EXIT_CODE}"
  fi
fi

echo "${RESULT_DIR}"
if [[ "${KEEP_ALIVE:-false}" == "true" ]]; then
  python3 "${PROJECT_ROOT}/Scripts/sunray/goal4_path_hold_from_csv.py" \
    --result-dir "${RESULT_DIR}" \
    --frame-id "${PX4CTRL_PATH_FRAME}" \
    --target-x "${TARGET_X}" \
    --target-y "${TARGET_Y}" \
    --target-z "${TARGET_Z}" \
    --publish-hz "${GOAL4_REVIEW_HOLD_PATH_PUBLISH_HZ}" \
    --max-points "${GOAL4_MAX_PATH_POINTS}" \
    --body-axis-length-m "${GOAL4_BODY_AXIS_LENGTH_M}" \
    --body-axis-shaft-m "${GOAL4_BODY_AXIS_SHAFT_M}" \
    --body-axis-head-diameter-m "${GOAL4_BODY_AXIS_HEAD_DIAMETER_M}" \
    --body-axis-head-length-m "${GOAL4_BODY_AXIS_HEAD_LENGTH_M}" \
    --body-axis-lifetime-s "${GOAL4_BODY_AXIS_LIFETIME_S}" \
    > "${RESULT_DIR}/goal4_path_hold_from_csv.log" 2>&1 &
  PIDS+=("$!")
  echo "KEEP_ALIVE=true; holding ROS/Gazebo/RViz processes for Goal4 visual review after final exit ${FINAL_EXIT_CODE}" \
    > "${RESULT_DIR}/keep_alive_status.txt"
  while true; do
    alive=0
    for pid in "${PIDS[@]:-}"; do
      if kill -0 "${pid}" >/dev/null 2>&1; then
        alive=1
      fi
    done
    if [[ "${alive}" -eq 0 ]]; then
      echo "all child processes exited" >> "${RESULT_DIR}/keep_alive_status.txt"
      exit "${FINAL_EXIT_CODE}"
    fi
    sleep 5
  done
fi
exit "${FINAL_EXIT_CODE}"
